local config = {
  ui_story_5079_50790100_1_dialog_content = "<color=#e8d9bb>Clac-clac, clac-clac—</color>",
  ui_story_5079_50790100_2_dialog_content = "¿Pact?",
  ui_story_5079_50790100_3_dialog_content = "<color=#e8d9bb>Clac-clac, clac-clac—</color>",
  ui_story_5079_50790100_4_dialog_content = "... ¿Mmm?",
  ui_story_5079_50790100_5_dialog_content = "\"¿Hmm\"? ¿En un momento como este, eso es realmente todo lo que tienes que decir? Por favor, explícate en este instante.",
  ui_story_5079_50790100_6_dialog_content = "Ah...",
  ui_story_5079_50790100_7_dialog_content = "No te equivoques, no estoy aquí para robarte el Maletín Blanco. Solo vine a sacar algo de dinero que dejé allí.",
  ui_story_5079_50790100_8_dialog_content = "... ¿Cuántas veces te he dicho que no pongas cosas dentro de mi Maletín Blanco? ¿Tienes idea de lo difícil que es hacer que las escupa de nuevo?",
  ui_story_5079_50790100_9_dialog_content = "Si vienes a extorsionarme, lo menos que puedes hacer es pensar en una mejor excusa.",
  ui_story_5079_50790100_10_dialog_content = "\"¿Extorsionar\"? ¡Nunca haría algo tan inapropiado! Simplemente no podía pensar en un lugar más seguro para guardar mi dinero, eso es todo...",
  ui_story_5079_50790100_11_dialog_content = "¡Pregúntale a tu Maletín Blanco si no me crees! Puedes comunicarte con él, ¿verdad?",
  ui_story_5079_50790100_12_dialog_content = "... Olvídalo. Ahora no es el mejor momento para que hagas un \"retiro\" del Maletín Blanco.",
  ui_story_5079_50790100_13_dialog_content = "Aquí, ¿es esto suficiente para ti?",
  ui_story_5079_50790100_14_dialog_content = "¿Estás intentando insultarme? ¿Qué es esta miseria?",
  ui_story_5079_50790100_15_dialog_content = "¿Y qué tal esto? ¿Todavía crees que es una miseria?",
  ui_story_5079_50790100_16_dialog_content = "Todavía no es suficiente.",
  ui_story_5079_50790100_17_dialog_content = "Entonces aquí, pero esto es lo último. Si hay más, comenzaré a sospechar de tus motivos.",
  ui_story_5079_50790100_18_dialog_content = "¿Podemos dejar de andar por las ramas ya? Solo dame todo el dinero que llevas ahora mismo, y podemos terminar aquí.",
  ui_story_5079_50790100_19_dialog_content = "¿Todo eso? ¿Finalmente estás cegado por el mal y por lo tanto requieres una cantidad exorbitante de dinero para llevar a cabo tus malvados actos?",
  ui_story_5079_50790100_20_dialog_content = "¿De qué estás hablando? ¡Solo necesito dinero para comprar ingredientes para nuestro <color=#FFB400>banquete</color>!",
  ui_story_5079_50790100_21_dialog_content = "Apenas tengo la oportunidad de asumir la responsabilidad de algo así. Es la oportunidad perfecta...",
  ui_story_5079_50790100_22_dialog_content = "Puedo mostrarles a todos lo que significa ejecutar una misión a la perfección. De esa manera, la gente dejará de tratarme como un personaje secundario.",
  ui_story_5079_50790100_23_dialog_content = "¿Estás consiguiendo ingredientes para nuestro <color=#FFB400>banquete</color>? ¿Y crees que puedes lograr una tarea tan importante con tus escasos ahorros?",
  ui_story_5079_50790100_24_dialog_content = "¡Humph! Confía en mí, tengo algunos trucos bajo la manga. ¡Ahora entrega todo tu dinero!",
  ui_story_5079_50790100_25_dialog_content = "Muy bien, pero si no logro recuperar la misma cantidad de dentro de mi Maletín Blanco, yo—",
  ui_story_5079_50790100_26_dialog_content = "¡Sí, sí, lo sé!",
  ui_story_5079_50790100_27_dialog_content = "Jejeje, ¡solo espera! Este próximo banquete dejará a todos boquiabiertos!",
  ui_story_5079_50790100_28_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790100_29_dialog_content = "Urgh... Mi cabeza...",
  ui_story_5079_50790100_30_dialog_content = "¿Me quedé dormido accidentalmente? Mi sueño también pareció muy largo... Pero, ¿de qué trataba?",
  ui_story_5079_50790100_31_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790100_32_dialog_content = "Espera... ¿Estoy en un tren?",
  ui_story_5079_50790100_33_dialog_content = "¡Rayos! No creo que tenga suficiente tiempo para comprar ropa nueva—",
  ui_story_5079_50790100_34_dialog_content = "¿Eh? Espera, mi ropa...",
  ui_story_5079_50790100_35_dialog_content = "Je, supongo que no estaba completamente despierto hace un momento. Parece que ya me cambié de ropa.",
  ui_story_5079_50790100_36_dialog_content = "Antes de realizar cualquier tipo de negocio, lo más importante que puedes hacer es lucir digno y presentable.",
  ui_story_5079_50790100_37_dialog_content = "Solo de esta manera los clientes ricos te darán su tiempo y su patrocinio.",
  ui_story_5079_50790100_38_dialog_content = "Eso es lo que él dijo... hace todos esos años.",
  ui_story_5079_50790100_39_dialog_content = "Aunque apenas puedo recordar cómo se ve, su insistencia aún zumba en mi cabeza...",
  ui_story_5079_50790100_40_dialog_content = "De todos modos, no puedo evitar confiar en él cuando se trata de hacer negocios.",
  ui_story_5079_50790100_41_dialog_content = "Después de todo, él podría haberse convertido en un poderoso comerciante en aquel entonces si no hubiera sido por mí... Je.",
  ui_story_5079_50790100_42_dialog_content = "<color=#e8d9bb>El tren está llegando ahora a <color=#FFB400>Folta Town</color>.</color>",
  ui_story_5079_50790100_43_dialog_content = "Folta... un pueblo famoso por sus mercados mayoristas de alimentos. Finalmente estoy casi allí, ¿eh?",
  ui_story_5079_50790100_44_dialog_content = "¡Apuesto a que esos vagos nunca se molestaron en venir hasta aquí por los ingredientes!",
  ui_story_5079_50790100_45_dialog_content = "Aun así, debería agradecerles por poner el listón tan bajo. Solo significa que los eclipsaré aún más cuando termine esto.",
  ui_story_5079_50790100_46_dialog_content = "Incluso podría conseguir mi deseo si hago esto bien, y ya no tendría que trabajar para esa cosa...",
  ui_story_5079_50790100_47_dialog_content = "Lo has hecho bien, Pact. Como recompensa, te concederé un deseo.",
  ui_story_5079_50790100_48_dialog_content = "Si recuerdo correctamente, tu deseo original... era deshacerte de la Piedra de Caza, ¿verdad?",
  ui_story_5079_50790100_49_dialog_content = "Cuando hayas tomado tu decisión, ven a buscarme.",
  ui_story_5079_50790100_50_dialog_content = "Dios mío, Pact! Estoy asombrado de que hayas logrado reunir ingredientes tan selectos para nuestro banquete.",
  ui_story_5079_50790100_51_dialog_content = "De hecho... Nunca podría lograr tal hazaña para mí mismo.",
  ui_story_5079_50790100_52_dialog_content = "Por favor, debes enseñarme tus métodos.",
  ui_story_5079_50790100_53_dialog_content = "Jeje... Jejejejeje...",
  ui_story_5079_50790100_54_dialog_content = "Perdóneme, señorita, pero parece que olvidó su equipaje.",
  ui_story_5079_50790100_55_dialog_content = "¿Eh? Creo que me estás confundiendo con otro pasajero. No soy el tipo de persona que pierde sus pertenencias.",
  ui_story_5079_50790100_56_dialog_content = "Lo siento, es solo que el equipaje coincide mucho con tu atuendo, así que asumí que te pertenecía.",
  ui_story_5079_50790100_57_dialog_content = "...",
  ui_story_5079_50790100_58_dialog_content = "Oh, ¿te refieres a la Piedra de Caza? No te preocupes, me sigue a donde quiera que vaya. No puedo deshacerme de ella incluso si quiero.",
  ui_story_5079_50790100_59_dialog_content = "Me sorprende que no te asustara. Eso es bastante raro.",
  ui_story_5079_50790100_60_dialog_content = "¿Asustado? ¡Por supuesto que no! De hecho, lo encuentro bastante encantador.",
  ui_story_5079_50790100_61_dialog_content = "(Parece que este conductor es bastante abierto de mente. No puedo contar cuántas veces la gente me ha rechazado por culpa de Hunting Stone.)",
  ui_story_5079_50790100_62_dialog_content = "(Incluso esas tiendas de ropa que afirman \"el cliente primero\" no me dedicarían ni un minuto del día...)",
  ui_story_5079_50790100_63_dialog_content = "D-Disculpe, pero... ¿q-qué diablos es esa cosa detrás de ti?",
  ui_story_5079_50790100_64_dialog_content = "Quizás sea mejor si pruebas con otra tienda, señorita. Aunque ciertamente puedes permitirte nuestra ropa, me temo que no podemos permitirnos perder clientes por culpa de tu... acompañante.",
  ui_story_5079_50790100_65_dialog_content = "No es necesario ofrecer más dinero, señorita...",
  ui_story_5079_50790100_66_dialog_content = "¿Puedo hacer una sugerencia? Si no te importa, ¿por qué no compras algo para hacer que tu amigo parezca... un poco menos intimidante?",
  ui_story_5079_50790100_67_dialog_content = "De lo contrario, temo que estropeará el aspecto de tu atuendo y tu dinero se habrá malgastado...",
  ui_story_5079_50790100_68_dialog_content = "¿Dices que se llama Piedra de Caza? ¡Qué nombre tan magnífico! Mi tren, Otro Fin, tiene un nombre igualmente impresionante.",
  ui_story_5079_50790100_69_dialog_content = "No recuerdo haber pedido el nombre de tu tren...",
  ui_story_5079_50790100_70_dialog_content = "Puedo ver que tu Piedra de Caza es muy similar a mi Otro Extremo, en el sentido de que ocupan lugares similares en nuestros corazones.",
  ui_story_5079_50790100_71_dialog_content = "Entonces podrías tener que revisarte los ojos, a menos que también quieras abandonar este tren. Para mí, Hunting Stone... no es más que un dolor.",
  ui_story_5079_50790100_72_dialog_content = "¡Jajaja! Nunca abandonaría a mi viejo amigo, y algo me dice... tú tampoco lo harías. Hasta la próxima vez que nos encontremos, mi señora.",
  ui_story_5079_50790100_73_dialog_content = "¿De qué diablos estaba hablando?",
  ui_story_5079_50790100_74_dialog_content = "Escucha, Piedra de Caza. Sé que no entiendes cuánto dinero gasté en estas decoraciones para ti...",
  ui_story_5079_50790100_75_dialog_content = "Pero tienes que prometer no asustar a nadie. ¡Esta misión significa todo para mí!",
  ui_story_5079_50790100_76_dialog_content = "!",
  ui_story_5079_50790100_77_dialog_content = "¡Bien! Ya que estamos en la misma página, puedes dejar de moverte más rápido que yo—",
  ui_story_5079_50790100_78_dialog_content = "¿Q-Qué es esta cosa?",
  ui_story_5079_50790100_79_dialog_content = "... Genial. Ni siquiera hemos bajado del tren y ya estamos asustando a la gente.",
  ui_story_5079_50790100_80_dialog_content = "Algo tan elegante debe pertenecer a una persona bastante importante...",
  ui_story_5079_50790100_81_dialog_content = "Ejem... Lo siento por eso. Lo sacaré de aquí ahora mismo.",
  ui_story_5079_50790100_82_dialog_content = "¿Tú? Dime, ¿eres uno de los ricos élites de Lumopolis, o quizás de Umbraton?",
  ui_story_5079_50790100_83_dialog_content = "¡Por favor disculpe mi rudeza justo ahora! No quise decir nada con eso...",
  ui_story_5079_50790100_84_dialog_content = "¿Por qué te estás disculpando? Soy yo el que está en tu camino, ¿verdad?",
  ui_story_5079_50790100_85_dialog_content = "Me siento honrado de haber compartido este tren contigo hoy, mi señora. Viajes seguros...",
  ui_story_5079_50790100_86_dialog_content = "T-Gracias.",
  ui_story_5079_50790100_87_dialog_content = "Tan raro... ¿Qué pasaba con ese tipo hace un momento? ¿Son mágicas estas ropas o algo así?",
  ui_story_5079_50790100_88_dialog_content = "¿Y por qué siento que lo he visto en algún lugar antes?",
  ui_story_5079_50790100_89_dialog_content = "Ah, olvídalo. Ahora no es el momento de preocuparse por estas cosas...",
  ui_story_5079_50790100_90_dialog_content = "*olfatea*",
  ui_story_5079_50790100_91_dialog_content = "¡Vaya, esos olores... Carne de res y tomates! ¡Galletas de crema y pan recién horneado! Y más...",
  ui_story_5079_50790100_92_dialog_content = "¡Eso es tan típico de Folta! ¡Ni siquiera hemos salido del tren y ya puedo oler tanta comida maravillosa!",
  ui_story_5079_50790100_93_dialog_content = "¡Parece que tendremos que probar algunos platos locales antes de ponernos a trabajar!",
  ui_story_5079_50790100_94_dialog_content = "!",
  ui_story_5079_50790200_1_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5079_50790200_2_dialog_content = "¡Así que este es Folta!",
  ui_story_5079_50790200_3_dialog_content = "La arquitectura es tan única. ¡Este lugar parece estar mucho más obsesionado con la comida que Umbraton!",
  ui_story_5079_50790200_4_dialog_content = "¿Eh? ¿Podría ser que estas casas están hechas de ingredientes reales?",
  ui_story_5079_50790200_5_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790200_6_dialog_content = "¡Ah... voy a perder el tren! ¡Disculpe!",
  ui_story_5079_50790200_7_dialog_content = "¿Eh?",
  ui_story_5079_50790200_8_dialog_content = "<color=#e8d9bb>¡Wham!</color>",
  ui_story_5079_50790200_9_dialog_content = "Ay...",
  ui_story_5079_50790200_10_dialog_content = "¡Acabo de comprar esta ropa también! ¡Apuesto a que están sucios ahora!",
  ui_story_5079_50790200_11_dialog_content = "¿Eh? No están sucios en todo. De hecho, están desprendiendo un dulce aroma... Espera, ¿estas rocas en el suelo están hechas de dulce?",
  ui_story_5079_50790200_12_dialog_content = "...",
  ui_story_5079_50790200_13_dialog_content = "¿Me pregunto a qué sabrán? Normalmente como rocas de Lumopolis para ayudar con la digestión, así que un pequeño mordisco no debería hacer daño...",
  ui_story_5079_50790200_14_dialog_content = "¡Ay!",
  ui_story_5079_50790200_15_dialog_content = "¿Ah?",
  ui_story_5079_50790200_16_dialog_content = "¿Qué crees que estás haciendo, señorita? ¡Estas piedras no son para comer!",
  ui_story_5079_50790200_17_dialog_content = "Je, dices tú... Además, ¿quién eres tú para decirme que no puedo comerlos?",
  ui_story_5079_50790200_18_dialog_content = "Parece que no entiendes, lo que probablemente significa que no eres de por aquí.",
  ui_story_5079_50790200_19_dialog_content = "Estas piedras son alimento para los <color=#FFB400>gorriones de caramelo</color>. ¡Es gracias a su ayuda que podemos construir nuestros edificios con comida!",
  ui_story_5079_50790200_20_dialog_content = "¿Cómo podrías pensar en privar de su comida a criaturas tan trabajadoras?",
  ui_story_5079_50790200_21_dialog_content = "¿Entonces estás diciendo que todos los edificios aquí realmente están hechos de comida?",
  ui_story_5079_50790200_22_dialog_content = "¡Ajá! Solo echa un vistazo a tu alrededor, las tablas del suelo están hechas de granos de cacao, y las farolas son paletas brillantes, y...",
  ui_story_5079_50790200_23_dialog_content = "¡Oye! ¿Qué le estás haciendo a esa farola?",
  ui_story_5079_50790200_24_dialog_content = "¡La pena por dañar la propiedad pública es grave! Te colgarán en la calle y dejarán que los gorriones de caramelo te picoteen hasta deshacerte...",
  ui_story_5079_50790200_25_dialog_content = "¿No sabes nada sobre este lugar?",
  ui_story_5079_50790200_26_dialog_content = "Suena a un montón de tonterías para mí. ¿Estás seguro de que no te lo estás inventando todo?",
  ui_story_5079_50790200_27_dialog_content = "¿Estás bromeando? ¡Esa es la razón por la que las calles de Folta están tan limpias y ordenadas!",
  ui_story_5079_50790200_28_dialog_content = "Sabes, señorita... Aunque estás vistiendo ropa tan sofisticada, estás actuando sin diferencia a un niño pequeño.",
  ui_story_5079_50790200_29_dialog_content = "¡Supongo que mi padre mentía cuando decía que las personas bien vestidas se comportan mejor que las demás!",
  ui_story_5079_50790200_30_dialog_content = "Dime... No robaste ese atuendo, ¿verdad? ¿Lo hiciste?",
  ui_story_5079_50790200_31_dialog_content = "¿Eh? Quiero que sepas que gasté una fortuna en estas ropas...",
  ui_story_5079_50790200_32_dialog_content = "(Hmm, no tengo que sentarme aquí y soportar esto de una niña pequeña.)",
  ui_story_5079_50790200_33_dialog_content = "(Ella no tiene respeto por sus mayores, ni límites para el caso... Pero por alguna razón, su actitud molesta es extrañamente familiar.)",
  ui_story_5079_50790200_34_dialog_content = "Hmm... Siento que chocar con esta extraña dama me hizo olvidar algo...",
  ui_story_5079_50790200_35_dialog_content = "<color=#e8d9bb>Choooooo—</color>",
  ui_story_5079_50790200_36_dialog_content = "¡Rayos, el tren! ¡Se fue!",
  ui_story_5079_50790200_37_dialog_content = "¡Todo esto es tu culpa! Primero me chocaste, luego desperdiciaste todo mi tiempo con tus tonterías, ¡y finalmente perdí el tren!",
  ui_story_5079_50790200_38_dialog_content = "¡Mi plan para huir de casa está arruinado! ¡Espero que estés listo para compensarme!",
  ui_story_5079_50790200_39_dialog_content = "¿Eh? ¿Estabas huyendo? ¿Y qué quieres decir con \"compensármelo\"?",
  ui_story_5079_50790200_40_dialog_content = "Tú eres el que chocó contra mí... ¡Si acaso, deberías ser tú quien me compense!",
  ui_story_5079_50790200_41_dialog_content = "Además, acabo de hacerte un gran favor al frustrar tu pequeño plan de escapar. Sería agradable un poco de gratitud, ¿no crees?",
  ui_story_5079_50790200_42_dialog_content = "¿Eh? ¡Estás soñando si crees que debería agradecerte! Además, te habrían picoteado hasta hacer pedazos si no hubiera sido por mí!",
  ui_story_5079_50790200_43_dialog_content = "¡Si alguien debería estar agradecido aquí, eres tú!",
  ui_story_5079_50790200_44_dialog_content = "¡No te equivoques, niño! ¡Solo hice eso porque estaba investigando ingredientes!",
  ui_story_5079_50790200_45_dialog_content = "¿No pensaste que iba a comer rocas solo porque tenía hambre, verdad? ¿Verdad?",
  ui_story_5079_50790200_46_dialog_content = "¡Y ahora me estás copiando! Urgh... Realmente eres inmaduro, ¿lo sabías?",
  ui_story_5079_50790200_47_dialog_content = "He terminado de discutir con este niño. Tengo un montón de compras que hacer, y todavía necesito visitar muchas tiendas y comparar sus precios.",
  ui_story_5079_50790200_48_dialog_content = "... ¡E-Espera!",
  ui_story_5079_50790200_49_dialog_content = "¿Ahora que?",
  ui_story_5079_50790200_50_dialog_content = "¿Estás aquí para comprar ingredientes, verdad? ¡Eso es a lo que se dedica el negocio de mi familia! ¿Te gustaría venir a nuestra tienda?",
  ui_story_5079_50790200_51_dialog_content = "¿Ahora quieres mi negocio después de toda esa discusión? Lo siento, pero no estoy interesado.",
  ui_story_5079_50790200_52_dialog_content = "<size=30>*suspiro* Otro fracaso...</size>",
  ui_story_5079_50790200_53_dialog_content = "(Papá siempre dice que no podemos permitirnos perder la oportunidad de hacer tratos con clientes adinerados como ella...)",
  ui_story_5079_50790200_54_dialog_content = "(Si puedo hacer que venga a nuestra tienda... ¡Apuesto a que papá me elogiará mucho! Tal vez olvide todo lo que pasó estos últimos días también.)",
  ui_story_5079_50790200_55_dialog_content = "(Pero lo más importante, puedo usar esto como una oportunidad para deshacerme de todas las cosas que no me gusta comer... ¡Heeheehee!)",
  ui_story_5079_50790200_56_dialog_content = "¡Siempre podría pedirle a mi padre que te dé un descuento increíble! ¡Piensa en ello como mi forma de compensarte!",
  ui_story_5079_50790200_57_dialog_content = "¿No estabas intentando huir de casa? ¿Por qué traerías a un extraño a casa y pedirías un descuento?",
  ui_story_5079_50790200_58_dialog_content = "Si yo fuera tu padre, nunca estaría de acuerdo con algo así.",
  ui_story_5079_50790200_59_dialog_content = "*lloriqueos* ¿Q-Qué debo hacer?",
  ui_story_5079_50790200_60_dialog_content = "¡Lo tengo! ¡Le diré que estabas preocupado por mi seguridad, por eso me trajiste a casa! ¡Estará tan agradecido que te ofrecerá una oferta única en la vida!",
  ui_story_5079_50790200_61_dialog_content = "Eso tiene sentido... Supongo que una buena acción no podría hacer daño.",
  ui_story_5079_50790200_62_dialog_content = "Solo recuerda, no puedo prometer que haré negocios con tu familia. Guía el camino, chico.",
  ui_story_5079_50790200_63_dialog_content = "¿Eh? ¿Qué es esa cosa detrás de ti?",
  ui_story_5079_50790200_64_dialog_content = "Finalmente te diste cuenta, ¿eh? No es demasiado tarde para tener miedo, ¡sabes! Especialmente ahora que sabes lo que pasará si me haces enojar...",
  ui_story_5079_50790200_65_dialog_content = "¡Guau, es tan lindo! ¡Y mira, puede moverse por sí solo! ¿Puedo acariciarlo? ¿Puedo?",
  ui_story_5079_50790200_66_dialog_content = "¡Oye, ya basta! ¡Esto no es un juguete!",
  ui_story_5079_50790200_67_dialog_content = "¿Por qué te estás molestando tanto? Solo quería acariciar a tu pequeño amigo...",
  ui_story_5079_50790200_68_dialog_content = "¿Mi \"pequeño amigo\"? ¿Crees que la Piedra de Caza es... Urgh, olvídalo.",
  ui_story_5079_50790200_69_dialog_content = "Noqueate a ti mismo, niño, pero vas a darme un descuento aún mayor cada vez que lo acaricies.",
  ui_story_5079_50790200_70_dialog_content = "O-Okay entonces... Solo lo acariciaré una vez...",
  ui_story_5079_50790200_71_dialog_content = "!",
  ui_story_5079_50790200_72_dialog_content = "¡Guau, es tan adorable! Se acurrucó junto a mí, ¡así que esas últimas caricias no cuentan!",
  ui_story_5079_50790200_73_dialog_content = "!",
  ui_story_5079_50790200_74_dialog_content = "(¿La Piedra de Caza la dejó tocarla? ¡Vaya, rueda inútil!)",
  ui_story_5079_50790200_75_dialog_content = "¡Muy bien, eso es suficiente! ¡Vámonos!",
  ui_story_5079_50790300_1_dialog_content = "¡Hmm, hmm, hmm!",
  ui_story_5079_50790300_2_dialog_content = "... ¿Por qué estás tan feliz?",
  ui_story_5079_50790300_3_dialog_content = "Eres el primer gran cliente que he traído a casa, ¡así que por supuesto que estoy feliz! ¡Papá va a estar tan contento conmigo!",
  ui_story_5079_50790300_4_dialog_content = "¿Sueles ayudar con el negocio de tu familia?",
  ui_story_5079_50790300_5_dialog_content = "Sí... Pero usualmente solo estorbo. De hecho, creo que soy la razón por la que nuestra tienda está yendo tan mal estos días.",
  ui_story_5079_50790300_6_dialog_content = "¡Pero ahora que estás aquí, las cosas finalmente podrían cambiar para nosotros!",
  ui_story_5079_50790300_7_dialog_content = "... Ni siquiera sé tu nombre, niño.",
  ui_story_5079_50790300_8_dialog_content = "¿Yo?",
  ui_story_5079_50790300_9_dialog_content = "¿Ah?",
  ui_story_5079_50790300_10_dialog_content = "Me llamo... <color=#FFB400>Popo</color>.",
  ui_story_5079_50790300_11_dialog_content = "¡Ah, no te hagas ideas locas! ¡Es solo un nombre! ¡Un nombre perfectamente normal!",
  ui_story_5079_50790300_12_dialog_content = "No iba a darle una segunda pensada, pero como hiciste un gran escándalo al respecto, ahora tengo ganas de preguntar...",
  ui_story_5079_50790300_13_dialog_content = "Es un nombre bastante lindo, ¿sabes?",
  ui_story_5079_50790300_14_dialog_content = "¡Muy bien, eso es suficiente! No estamos aquí para discutir la ternura de los nombres, ¡ahora vamos!",
  ui_story_5079_50790300_15_dialog_content = "¡Este es el lugar!",
  ui_story_5079_50790300_16_dialog_content = "¿En serio? No se siente muy profesional...",
  ui_story_5079_50790300_17_dialog_content = "Hmm... ¿Padre? ¿Estás en casa?",
  ui_story_5079_50790300_18_dialog_content = "Bueno, no quiero ser grosero, pero hay un cartel de \"cerrado\" en la puerta.",
  ui_story_5079_50790300_19_dialog_content = "Parece que tu tienda no ha estado abierta durante un tiempo. ¿No estabas al tanto de eso?",
  ui_story_5079_50790300_20_dialog_content = "?",
  ui_story_5079_50790300_21_dialog_content = "¡No tengo idea de lo que estás hablando!",
  ui_story_5079_50790300_22_dialog_content = "¡A mi padre le encanta su tienda y la mantiene abierta todos los días del año! ¿Cómo podría estar cerrada?",
  ui_story_5079_50790300_23_dialog_content = "¿Por qué no echas un vistazo tú mismo? Aquí dice, \"Tienda cerrada por motivos familiares.\"",
  ui_story_5079_50790300_24_dialog_content = "(Sabía que no debería haberme involucrado con este niño. Ya he perdido demasiado tiempo.)",
  ui_story_5079_50790300_25_dialog_content = "(Si no logro esto a la perfección, quién sabe cuánto se burlarán de mí...)",
  ui_story_5079_50790300_26_dialog_content = "Lo siento, Popo, pero no puedo hacer negocios con tu familia si no hay negocio en absoluto. Debería irme-",
  ui_story_5079_50790300_27_dialog_content = "*sollozando*... <size=45>¡Waaaaaaaaahhh!</size>",
  ui_story_5079_50790300_28_dialog_content = "¡Oye, no llores! La gente va a pensar que te estoy molestando.",
  ui_story_5079_50790300_29_dialog_content = "¡Eso es porque TÚ te estás metiendo conmigo!",
  ui_story_5079_50790300_30_dialog_content = "¡Si no hubiera perdido mi tren, ya habría desaparecido hace mucho tiempo! ¡Entonces nunca habría descubierto que mi papá realmente ya no me quiere!",
  ui_story_5079_50790300_31_dialog_content = "Pero aún así, llorar no resolverá nada. ¿Tienes a alguien más en quien confiar además de tu papá?",
  ui_story_5079_50790300_32_dialog_content = "No... Mi mamá falleció hace mucho tiempo. Papá y yo nos hemos estado cuidando mutuamente desde entonces...",
  ui_story_5079_50790300_33_dialog_content = "Pero discutimos todo el tiempo... Y durante nuestra última pelea, dijo que no necesitaba a una hija desobediente como yo.",
  ui_story_5079_50790300_34_dialog_content = "¡También estaba furioso con él! Tan furioso que me escapé de casa...",
  ui_story_5079_50790300_35_dialog_content = "No tenía idea de que realmente se iría... Papá realmente ya no me quiere... ¡Waaaaah!",
  ui_story_5079_50790300_36_dialog_content = "Pero es normal discutir con tu papá, ¿no es así?",
  ui_story_5079_50790300_37_dialog_content = "*olfatea*... ¿Eso significa que también discutes con tu padre?",
  ui_story_5079_50790300_38_dialog_content = "Lo hice, y fue bastante malo también. Se negó a aceptarme a mí o a mi Piedra de Caza aquí, la que tú crees que es tan linda.",
  ui_story_5079_50790300_39_dialog_content = "...",
  ui_story_5079_50790300_40_dialog_content = "Así que me dejó algo de dinero, y luego nunca más lo volví a ver...",
  ui_story_5079_50790300_41_dialog_content = "¿Eh? ¿Quieres decir que tu padre realmente te dejó algo de dinero?",
  ui_story_5079_50790300_42_dialog_content = "¡Pero mi padre no me dejó nada antes de abandonarme!",
  ui_story_5079_50790300_43_dialog_content = "<size=50>¡Waaaaaaaaaah!</size>",
  ui_story_5079_50790300_44_dialog_content = "¡No digas eso, Popo! Tu padre te dejó esta tienda, ¿no es así?",
  ui_story_5079_50790300_45_dialog_content = "Estoy bastante seguro de que eso te hace el jefe por aquí, ¿verdad? Si es así, ¿podría comprarte esta mesa de chocolate? ¡Tengo bastante hambre!",
  ui_story_5079_50790300_46_dialog_content = "Parece un poco duro, pero apuesto a que sabe genial. Mira, ¡incluso tiene una capa de glaseado en la parte superior!",
  ui_story_5079_50790300_47_dialog_content = "¿Oh? ¿El vidrio de ese gabinete está hecho de azúcar moreno caramelizado?",
  ui_story_5079_50790300_48_dialog_content = "¡Y ese jarrón es en realidad un tarro de miel! ¿Puedo sumergir esto en miel? El jarrón también parece bastante sabroso...",
  ui_story_5079_50790300_49_dialog_content = "¡Ahhhh! ¡Deja de intentar comer los muebles! ¡Todavía es mi casa, sabes!",
  ui_story_5079_50790300_50_dialog_content = "¡Realmente no tienes modales en absoluto, ni gusto por cierto!",
  ui_story_5079_50790300_51_dialog_content = "Quiero decir, ¿qué tipo de persona sumerge los dulces duros en miel? ¿Estás intentando pudrir tus dientes?",
  ui_story_5079_50790300_52_dialog_content = "Oh bien, ya no estás llorando.",
  ui_story_5079_50790300_53_dialog_content = "¿Eh? ¿Estabas tratando de animarme?",
  ui_story_5079_50790300_54_dialog_content = "No, simplemente tengo mucha, mucha hambre.",
  ui_story_5079_50790300_55_dialog_content = "Bueno... ¡Eso sigue sin ser excusa para que te comas nuestros muebles!",
  ui_story_5079_50790300_56_dialog_content = "Todavía tenemos muchas zanahorias en stock, así que sírvete de esas.",
  ui_story_5079_50790300_57_dialog_content = "¿Zanahorias? Puaj...",
  ui_story_5079_50790300_58_dialog_content = "¿Qué? ¿Tampoco te gustan las zanahorias?",
  ui_story_5079_50790300_59_dialog_content = "Eso ni siquiera se acerca a describir mi odio hacia ellas... ¡Las zanahorias son la comida más aterradora del mundo!",
  ui_story_5079_50790300_60_dialog_content = "¡Lo sé! ¡Lo sé!",
  ui_story_5079_50790300_61_dialog_content = "¡Las zanahorias ni siquiera deberían existir en este mundo! ¡Fueron la razón principal por la que tuve esa pelea con mi papá!",
  ui_story_5079_50790300_62_dialog_content = "Dijo que era inaceptable que la hija de un vendedor de zanahorias odiara comer zanahorias, y que estaba avergonzando el negocio de nuestra familia...",
  ui_story_5079_50790300_63_dialog_content = "¡Pero no hay ninguna regla que diga que tengo que gustarme las zanahorias solo porque mi papá las vende para ganarse la vida!",
  ui_story_5079_50790300_64_dialog_content = "Je, no esperaba estar completamente de acuerdo contigo en algo, pero aquí estamos.",
  ui_story_5079_50790300_65_dialog_content = "Estabas planeando venderme todas las zanahorias de tu familia, para no tener que comértelas, ¿verdad?",
  ui_story_5079_50790300_66_dialog_content = "Bueno, no... Solo iba a vender la mitad de ellos y dejar el resto para mi padre, ya que le gustan tanto.",
  ui_story_5079_50790300_67_dialog_content = "Lo hace, ¿eh?... No es de extrañar que te llamara \"Popo\". ¡Apuesto a que es porque quería que tú también amaras las zanahorias!",
  ui_story_5079_50790300_68_dialog_content = "¡Humph! ¡No hay nada malo en no gustar las zanahorias! Podría haberme llamado \"Zanahoria\", ¡y aún así pensaría que son asquerosas!",
  ui_story_5079_50790300_69_dialog_content = "Entonces, incluso después de todo lo que ha pasado, ¿todavía quieres dejarle algunas zanahorias a tu papá para comer?",
  ui_story_5079_50790300_70_dialog_content = "Ah... Esa era mi idea de antes, ¡pero ya no! ¡Voy a deshacerme de todas estas malditas zanahorias ahora!",
  ui_story_5079_50790300_71_dialog_content = "¿Todavía amas a tu padre?",
  ui_story_5079_50790300_72_dialog_content = "¡P-Por supuesto que no! ¿Por qué me importaría él después de que me abandonó así? ¡Humph!",
  ui_story_5079_50790300_73_dialog_content = "Pero, ¿qué pasa si en realidad no te abandonó?",
  ui_story_5079_50790300_74_dialog_content = "Bueno, uh... ¡Tendremos que esperar y ver!",
  ui_story_5079_50790300_75_dialog_content = "(Los niños pequeños son demasiado predecibles... No creo que su padre sea tan malo como ella dice.)",
  ui_story_5079_50790300_76_dialog_content = "(Probablemente solo está intentando imponer sus preferencias a su hija, por eso pelean tanto. Es un error, pero uno que comete por amor.)",
  ui_story_5079_50790300_77_dialog_content = "(Un hueco tan pequeño es fácil de cubrir.)",
  ui_story_5079_50790300_78_dialog_content = "Parece que tus problemas con tu padre son bastante pequeños, al menos en comparación con los míos.",
  ui_story_5079_50790300_79_dialog_content = "Una vez, cuando mi padre intentó obligarme a comer zanahorias, comí un puñado de piedras solo para vengarme de él...",
  ui_story_5079_50790300_80_dialog_content = "¡Oh! ¡Así que por eso estabas tan dispuesto a comer esas rocas antes!",
  ui_story_5079_50790300_81_dialog_content = "¡No tenía nada que ver con que seas inmaduro o que no tengas gusto en absoluto!",
  ui_story_5079_50790300_82_dialog_content = "... ¿Te costaría ser más educado de vez en cuando? Recuerda, ¡eres tú quien me debe a mí!",
  ui_story_5079_50790400_1_dialog_content = "¿Ya te sientes mejor? Deberías, después de toda esa charla...",
  ui_story_5079_50790400_2_dialog_content = "Solo recuerda, cada nube oscura tiene un borde plateado. Puede que nos hayan abandonado, pero al menos ahora somos libres.",
  ui_story_5079_50790400_3_dialog_content = "Y si mi padre no me hubiera dejado, nunca habría conocido... No importa, todavía eres demasiado joven para saber sobre eso.",
  ui_story_5079_50790400_4_dialog_content = "¡No me importa eso!",
  ui_story_5079_50790400_5_dialog_content = "¡No voy a tomar esto tumbado! ¡Voy a vengarme de papá!",
  ui_story_5079_50790400_6_dialog_content = "¿Crees que podría pedir prestada tu rueda por un rato? ¡Quiero usarla para atropellarlo unas cuantas veces!",
  ui_story_5079_50790400_7_dialog_content = "...",
  ui_story_5079_50790400_8_dialog_content = "... Te lo dije, se llama Piedra de Caza.",
  ui_story_5079_50790400_9_dialog_content = "Y aunque me encantaría prestartelo... se niega a separarse de mi lado, siempre.",
  ui_story_5079_50790400_10_dialog_content = "Además, no deberías alterarte tanto por esto, Popo. Algo me dice que tu padre en realidad no te abandonó.",
  ui_story_5079_50790400_11_dialog_content = "Pero ya te conté todo sobre lo que pasó...",
  ui_story_5079_50790400_12_dialog_content = "Sí, después de ver la tienda y pensarlo un poco, creo que tengo una buena idea de lo que está pasando.",
  ui_story_5079_50790400_13_dialog_content = "¿Ves? Las zanahorias en estos montones están claramente aún frescas. Eso me dice que acaban de llegar y él estaba preparándose para venderlas.",
  ui_story_5079_50790400_14_dialog_content = "Además, ninguno de los objetos de valor en tu casa falta. Eso no es algo que haría si planeaba irme.",
  ui_story_5079_50790400_15_dialog_content = "No dejaría todas sus posesiones tiradas así a menos que...",
  ui_story_5079_50790400_16_dialog_content = "¿A menos que?",
  ui_story_5079_50790400_17_dialog_content = "A menos que tuviera tantas deudas que no pudiera pagarlas todas. Puede evitar sospechas y escapar mucho más fácilmente si deja todo exactamente donde está.",
  ui_story_5079_50790400_18_dialog_content = "Oh...",
  ui_story_5079_50790400_19_dialog_content = "¿Q-Qué pasa con esa mirada?",
  ui_story_5079_50790400_20_dialog_content = "¡Para alguien tan inmaduro como tú, no tenía idea de que pudieras ser tan racional!",
  ui_story_5079_50790400_21_dialog_content = "¿Todavía me llamas inmaduro, eh...",
  ui_story_5079_50790400_22_dialog_content = "Dejémoslo. Discutir sobre eso solo nos hace a ambos inmaduros.",
  ui_story_5079_50790400_23_dialog_content = "Pero ahora que lo mencionas...",
  ui_story_5079_50790400_24_dialog_content = "Estoy bastante seguro de que mi padre realmente pidió prestado dinero a... la <color=#FFB400>Familia Ketchup</color>!",
  ui_story_5079_50790400_25_dialog_content = "¡Pero esa deuda debería haberse pagado hace mucho tiempo! ¿Podría papá haber pedido prestado más dinero sin decírmelo?",
  ui_story_5079_50790400_26_dialog_content = "Apenas creo que tu padre tenga alguna necesidad de hablarte sobre sus deudas...",
  ui_story_5079_50790400_27_dialog_content = "¡Eso es! ¡He tomado mi decisión!",
  ui_story_5079_50790400_28_dialog_content = "Genial... ¿Y cuál sería esa brillante decisión?",
  ui_story_5079_50790400_29_dialog_content = "¡Voy a visitar a la familia Ketchup! ¡Incluso podrían saber dónde está mi padre ahora mismo!",
  ui_story_5079_50790400_30_dialog_content = "¿Oh? Eso es realmente una muy buena idea.",
  ui_story_5079_50790400_31_dialog_content = "(Por fin puedo dejar de cuidar a este niño ahora...)",
  ui_story_5079_50790400_32_dialog_content = "Espero que la Familia Ketchup tenga las respuestas que estás buscando, niño. Ahora bien, realmente debería ser...",
  ui_story_5079_50790400_33_dialog_content = "¡E-Espera! ¡No puedes irte aún!",
  ui_story_5079_50790400_34_dialog_content = "¿Ah?",
  ui_story_5079_50790400_35_dialog_content = "Jeje, hay una razón por la que sigo llamándote inmaduro, ¿sabes?",
  ui_story_5079_50790400_36_dialog_content = "¡Si te vas ahora, te arrepentirás por el resto de tu vida!",
  ui_story_5079_50790400_37_dialog_content = "¿Y por qué es eso?",
  ui_story_5079_50790400_38_dialog_content = "La Familia Ketchup siempre ha estado a cargo de esta ciudad. ¡También dirigen la tienda de tomates más grande de todo Astra!",
  ui_story_5079_50790400_39_dialog_content = "¡Si estás buscando los mejores ingredientes, no puedes permitirte perdértelos!",
  ui_story_5079_50790400_40_dialog_content = "Debes haber hecho tu investigación antes de venir a Folta, ¿verdad? ¿Verdad?",
  ui_story_5079_50790400_41_dialog_content = "Tenemos un viejo dicho por aquí: \"¡Cualquiera que venga a Folta sin hacer negocios con la Familia Ketchup es un tonto!\"",
  ui_story_5079_50790400_42_dialog_content = "¿Seguro que no te estás inventando ese \"viejo dicho\", niño?",
  ui_story_5079_50790400_43_dialog_content = "De todos modos, ¡me siento bastante generoso hoy! ¡Ven conmigo y te presentaré personalmente a la Familia Ketchup!",
  ui_story_5079_50790400_44_dialog_content = "\"Generoso\", ¿eh? Solo estás demasiado asustado para verlos por tu cuenta, ¿verdad?",
  ui_story_5079_50790400_45_dialog_content = "Después de todo, estoy seguro de que una familia adinerada como esa no tiene tiempo para niños pequeños como tú...",
  ui_story_5079_50790400_46_dialog_content = "Y tú pensabas que estabas listo para escaparte de casa...",
  ui_story_5079_50790400_47_dialog_content = "¡E-Eso no es en absoluto! S-Solo estoy haciendo esto por tu bien...",
  ui_story_5079_50790400_48_dialog_content = "¡Humph, bien, puedes olvidarte de todo ahora! Disfruta siendo una tonta, lady, ¡y voy a ir a verlos a todos por mi cuenta!",
  ui_story_5079_50790400_49_dialog_content = "Así que ahora soy inmaduro Y un tonto...",
  ui_story_5079_50790400_50_dialog_content = "¡Tsk! Mocosos groseros como ella simplemente tienen que aprender las cosas de la manera difícil.",
  ui_story_5079_50790400_51_dialog_content = "Urgh, pero ¿por qué estoy tan inquieto?",
  ui_story_5079_50790400_52_dialog_content = "Si no mentía sobre la Familia Ketchup, entonces definitivamente tengo que hacerles una visita.",
  ui_story_5079_50790400_53_dialog_content = "Además, no estoy seguro de que Popo llegue muy lejos con ese temperamento suyo. Si algo le sucede a ella...",
  ui_story_5079_50790400_54_dialog_content = "En realidad no estoy preocupado por ella ni nada... pero muchas personas nos vieron juntos antes.",
  ui_story_5079_50790400_55_dialog_content = "Si algo le sucede a ella, cada persona en este pueblo insignificante vendrá tras de mí, ya que soy un forastero...",
  ui_story_5079_50790400_56_dialog_content = "¡Hola Popo! ¡Espera!",
  ui_story_5079_50790400_57_dialog_content = "¡Humph! ¿Te conozco?",
  ui_story_5079_50790400_58_dialog_content = "También resulta que voy en esta dirección. ¿Quieres caminar juntos?",
  ui_story_5079_50790400_59_dialog_content = "¡No!",
  ui_story_5079_50790400_60_dialog_content = "Aunque... Si me ruegas que te deje caminar conmigo, podría reconsiderarlo.",
  ui_story_5079_50790400_61_dialog_content = "Como dije, solo pasa que voy en la misma dirección...",
  ui_story_5079_50790400_62_dialog_content = "¿Qué te parece esto? Caminas conmigo y te ayudaré a preguntarle a la Familia Ketchup sobre tu papá.",
  ui_story_5079_50790400_63_dialog_content = "Eres una chica bastante inteligente, así que estoy seguro de que tomarás la decisión correcta.",
  ui_story_5079_50790400_64_dialog_content = "Mmm...",
  ui_story_5079_50790400_65_dialog_content = "Está bien, pero tienes que caminar detrás de mí todo el tiempo!",
  ui_story_5079_50790400_66_dialog_content = "¡Y no te pierdas! ¡No tengo ganas de buscarte si lo haces!",
  ui_story_5079_50790400_67_dialog_content = "(Los niños son un gran dolor de cabeza...)",
  ui_story_5079_50790400_68_dialog_content = "Está bien, vamos.",
  ui_story_5079_50790500_1_dialog_content = "B-Bueno... A-Aquí estamos! ¡V-Vamos adentro!",
  ui_story_5079_50790500_2_dialog_content = "¿Estás bien? Estás tartamudeando mucho... No estás nervioso, ¿verdad?",
  ui_story_5079_50790500_3_dialog_content = "¡P-Por supuesto que no! S-Solo estoy un poco emocionado, eso es todo.",
  ui_story_5079_50790500_4_dialog_content = "Después de todo, nos vamos a reunir con la cabeza de la Familia Ketchup... ¡R-realmente tengo mucho respeto por ella!",
  ui_story_5079_50790500_5_dialog_content = "Pero ir a su casa sin invitación y vestido así... ¿C-Crees que causaré una mala impresión en ella?",
  ui_story_5079_50790500_6_dialog_content = "Te preocupas mucho para alguien de tu edad, Popo.",
  ui_story_5079_50790500_7_dialog_content = "Pero estarás bien. Solo quédate detrás de mí y déjame hablar por ti.",
  ui_story_5079_50790500_8_dialog_content = "Ah, veo que tenemos una invitada de lejos. Bienvenida, mi señora.",
  ui_story_5079_50790500_9_dialog_content = "Veo que traes a alguien contigo... un pequeño de aspecto familiar.",
  ui_story_5079_50790500_10_dialog_content = "Debo decir, ustedes dos hacen un dúo bastante interesante. Dime, ¿qué los trae por aquí hoy?",
  ui_story_5079_50790500_11_dialog_content = "Vine porque... Espera un minuto, ¿no nos hemos visto antes?",
  ui_story_5079_50790500_12_dialog_content = "Creo que está equivocada, mi señora. Aunque hasta ahora no he dado la bienvenida a pocos invitados...",
  ui_story_5079_50790500_13_dialog_content = "Estoy seguro de que recordaría a una joven tan hermosa y de aspecto noble como tú.",
  ui_story_5079_50790500_14_dialog_content = "E-Es eso así...",
  ui_story_5079_50790500_15_dialog_content = "!(Sabía que comprar estas ropas era lo correcto! Es hora de probar un poco mi suerte...)",
  ui_story_5079_50790500_16_dialog_content = "*observa*",
  ui_story_5079_50790500_17_dialog_content = "<size=30>Lo sé, lo sé! Te di mi palabra, ahora deja de mirarme así!</size>",
  ui_story_5079_50790500_18_dialog_content = "Ejem... Mis razones para venir aquí son dobles...",
  ui_story_5079_50790500_19_dialog_content = "Una de esas razones es que esta chica afirma que su padre la ha abandonado. Sospechamos que tu familia está de alguna manera conectada con este asunto, por lo que vinimos a preguntar.",
  ui_story_5079_50790500_20_dialog_content = "... ¡Oye! ¡No seas tan directo al respecto!",
  ui_story_5079_50790500_21_dialog_content = "Esto es un malentendido bastante extraño.",
  ui_story_5079_50790500_22_dialog_content = "¿Quieres decir que tu padre aún no te ha encontrado, Popo?",
  ui_story_5079_50790500_23_dialog_content = "¿Me encontraste?",
  ui_story_5079_50790500_24_dialog_content = "Sí. Después de buscarte por todas partes, concluyó que ya te habías ido en un tren, así que compró un boleto para el próximo viaje de salida.",
  ui_story_5079_50790500_25_dialog_content = "Y sin embargo, aquí estás. Un divertido giro del destino, ¿no crees?",
  ui_story_5079_50790500_26_dialog_content = "¿De verdad? ¿De verdad? ¿Padre solo cerró la tienda para poder venir a buscarme?",
  ui_story_5079_50790500_27_dialog_content = "Por supuesto. ¿Quién más cuidaría la tienda en su ausencia?",
  ui_story_5079_50790500_28_dialog_content = "P-P-Pero entonces...",
  ui_story_5079_50790500_29_dialog_content = "¿Cómo se supone que debo encontrarlo? Quién sabe qué tan lejos ha tomado el tren... Nunca hubiera intentado escapar si hubiera sabido que esto sucedería...",
  ui_story_5079_50790500_30_dialog_content = "No te preocupes, Popo.",
  ui_story_5079_50790500_31_dialog_content = "El conductor del tren es parte de la Familia Ketchup. Le diré que le diga a tu padre que vuelva a casa lo antes posible.",
  ui_story_5079_50790500_32_dialog_content = "¿En serio? ¿De verdad? ¡Oh, muchas gracias!",
  ui_story_5079_50790500_33_dialog_content = "(Uf... Eso es una cosa menos de qué preocuparse.)",
  ui_story_5079_50790500_34_dialog_content = "(El padre de Popo estaba dispuesto a cerrar su negocio, que tanto le costó ganar, solo para buscar a su hija.)",
  ui_story_5079_50790500_35_dialog_content = "(Si fuera mi padre, humph, probablemente se sentiría aliviado.)",
  ui_story_5079_50790500_36_dialog_content = "Eso me recuerda, ¡señora! Esta inmadura... quiero decir, sofisticada mujer joven vino a Folta por asuntos importantes!",
  ui_story_5079_50790500_37_dialog_content = "Oye, nadie te pidió que te metieras...",
  ui_story_5079_50790500_38_dialog_content = "Necesita comprar muchos ingredientes de primera calidad, ¡así que pensé que debería traerla a verte primero!",
  ui_story_5079_50790500_39_dialog_content = "Definitivamente puedes ayudarla, ¿no es así?",
  ui_story_5079_50790500_40_dialog_content = "(Oh... ¿Es esta la forma de Popo de agradecerme? Supongo que la dejaré terminar entonces...)",
  ui_story_5079_50790500_41_dialog_content = "(Además... podría acostumbrarme a que me llamen \"dama sofisticada\".)",
  ui_story_5079_50790500_42_dialog_content = "Gracias, Popo. Estaría más que feliz de organizar algo.",
  ui_story_5079_50790500_43_dialog_content = "Con la posición de la Familia Ketchup en Folta, puedo hacer que todas las tiendas envíen sus mejores ingredientes aquí para tu selección.",
  ui_story_5079_50790500_44_dialog_content = "Después de un viaje tan largo, dudo que quieras corretear por la ciudad buscándolos.",
  ui_story_5079_50790500_45_dialog_content = "Y como eres tan amable de ayudar al pequeño Popo, puedo ayudarte a comprarlos al precio más bajo posible. ¿Eso sería satisfactorio?",
  ui_story_5079_50790500_46_dialog_content = "Si no es mucho pedir, entonces sí, ¡absolutamente!",
  ui_story_5079_50790500_47_dialog_content = "Simplemente dejaré mi lista de compras contigo, ejem, muchas gracias por tu ayuda.",
  ui_story_5079_50790500_48_dialog_content = "No te preocupes. Comenzaré a recoger estos artículos de inmediato.",
  ui_story_5079_50790500_49_dialog_content = "¡Jejeje!",
  ui_story_5079_50790500_50_dialog_content = "Te ves terriblemente engreído, Popo.",
  ui_story_5079_50790500_51_dialog_content = "Bueno, acabo de ayudarte a conseguir un buen trato. ¡Espero que estés listo para compensarme después!",
  ui_story_5079_50790500_52_dialog_content = "Estoy bastante seguro de que podría haberlo hecho yo mismo... no importa.",
  ui_story_5079_50790500_53_dialog_content = "La verdad es que realmente me ayudaste. ¿Cómo quieres que te pague?",
  ui_story_5079_50790500_54_dialog_content = "¿Qué tal si te quedas hasta que encuentre a mi padre?",
  ui_story_5079_50790500_55_dialog_content = "¿Eh... Te refieres a cuidarte un poco más? Claro que sí, niño.",
  ui_story_5079_50790500_56_dialog_content = "¡T-Tú no me estás \"cuidando\"! Nos estamos ayudando mutuamente, ¿de acuerdo?",
  ui_story_5079_50790500_57_dialog_content = "¡Y te ayudé mucho, recuerdas? ¡Tienes que al menos igualarlo!",
  ui_story_5079_50790500_58_dialog_content = "Entonces permíteme endulzar el trato con una oferta que no puedes rechazar.",
  ui_story_5079_50790500_59_dialog_content = "Cuando tu padre regrese, lo convenceré de que deje de obligarte a comer zanahorias.",
  ui_story_5079_50790500_60_dialog_content = "Estoy bastante familiarizado con este tipo de cosas, especialmente cuando se trata de persuadir y molestar. También ayuda que tenga setenta y cuatro razones por las que no se deberían comer zanahorias.",
  ui_story_5079_50790500_61_dialog_content = "¿En serio? ¡Eso es increíble! Hasta ahora solo he podido encontrar treinta y tres razones...",
  ui_story_5079_50790500_62_dialog_content = "Si realmente logras hacer esto... ¡Seré tu seguidor de por vida!",
  ui_story_5079_50790500_63_dialog_content = "Perdóneme, pero la señora de la casa ha preparado una deliciosa comida para nuestros dos estimados invitados. Por favor, síganme al comedor, si les parece bien.",
  ui_story_5079_50790500_64_dialog_content = "Esta será la oportunidad perfecta para que también pruebes las diferentes delicias de nuestro pueblo, señora. Si tiene alguna sugerencia sobre la comida, compártala con nosotros de manera respetuosa.",
  ui_story_5079_50790500_65_dialog_content = "Si no demuestras el nivel adecuado de respeto hacia nuestra gente, especialmente hacia el jefe de la Familia Ketchup...",
  ui_story_5079_50790500_66_dialog_content = "Puede que tenga que tomar medidas en tu contra.",
  ui_story_5079_50790500_67_dialog_content = "No creo que necesites llegar tan lejos, ¿verdad?",
  ui_story_5079_50790500_68_dialog_content = "Elegí hacer negocios con la Familia Ketchup por un sentido de confianza mutua.",
  ui_story_5079_50790500_69_dialog_content = "Entonces por favor perdóname por mis insinuaciones insensibles... Pero hay una sensación de inquietud en mi corazón que no desaparece...",
  ui_story_5079_50790500_70_dialog_content = "En cualquier caso, por aquí.",
  ui_story_5079_50790500_71_dialog_content = "¡Finalmente voy a comer! Todo este tiempo me he estado preguntando a qué sabe la comida de Folta...",
  ui_story_5079_50790500_72_dialog_content = "¡Jejeje!",
  ui_story_5079_50790500_73_dialog_content = "Realmente no sabes cómo ocultar tus emociones, ¿verdad? Recuerda, vamos a cenar con el jefe de la Familia Ketchup.",
  ui_story_5079_50790500_74_dialog_content = "Intenta comportarte un poco más como una dama, ¿lo harías?",
  ui_story_5079_50790500_75_dialog_content = "¿Ahora tú también me estás dando una conferencia? Suenas tan molesto como mi padre...",
  ui_story_5079_50790500_76_dialog_content = "De todos modos, sabes lo que significa cenar con la Familia Ketchup, ¿no?",
  ui_story_5079_50790500_77_dialog_content = "¡Significa que todo está hecho con tomates! ¡Lo que también significa que no habrá ni una sola zanahoria apestosa a la vista!",
  ui_story_5079_50790500_78_dialog_content = "Eso es definitivamente algo por lo que esperar, pero... ¿Realmente soné como tu padre justo ahora?",
  ui_story_5079_50790500_79_dialog_content = "Sí. Siempre me dice cómo comportarme en la mesa, ¡como si alguna vez le hiciera caso!",
  ui_story_5079_50790500_80_dialog_content = "Deberías estar feliz de que finalmente podamos comer, ¡así que deja de pensar demasiado las cosas!",
  ui_story_5079_50790500_81_dialog_content = "Lo sé, solo...",
  ui_story_5079_50790500_82_dialog_content = "(Solo no quiero convertirme en otro adulto terco como ese...)",
  ui_story_5079_50790500_83_dialog_content = "Por favor, perdónanos si la comida no es tan grandiosa como se esperaba. Nuestros chefs hicieron todo lo que pudieron lo más rápido posible.",
  ui_story_5079_50790500_84_dialog_content = "No te preocupes, todos estos platos rojos son suficientes para abrir mi apetito!",
  ui_story_5079_50790500_85_dialog_content = "¿Podemos comer ahora? ¿Podemos?",
  ui_story_5079_50790500_86_dialog_content = "Por favor Ayúdense ustedes mismos.",
  ui_story_5079_50790500_87_dialog_content = "¡Quiero probar primero el bisque de tomate! ¡Solo de pensar en ese sabor dulce y agrio se me hace la boca agua!",
  ui_story_5079_50790500_88_dialog_content = "¡Espera, hagamos esto juntos! ¡Tres, dos, uno, vamos!",
  ui_story_5079_50790500_89_dialog_content = "Por favor, no me hagas hacer algo tan tonto...",
  ui_story_5079_50790500_90_dialog_content = "¡Vamos! ¿Por favor?",
  ui_story_5079_50790500_91_dialog_content = "Bien... Tres, dos...",
  ui_story_5079_50790500_92_dialog_content = "¡Uno!",
  ui_story_5079_50790500_93_dialog_content = "*sorbe*",
  ui_story_5079_50790500_94_dialog_content = "...",
  ui_story_5079_50790500_95_dialog_content = "...",
  ui_story_5079_50790500_96_dialog_content = "<size=45>¡Pfffffffft!</size>",
  ui_story_5079_50790500_97_dialog_content = "¡Está envenenado! ¡La sopa está envenenada! ¡Alguien está tratando de acabar con nosotros!",
  ui_story_5079_50790500_98_dialog_content = "¡Esto es absolutamente inaceptable! ¿Tus personas hicieron esto a propósito?",
  ui_story_5079_50790500_99_dialog_content = "Me niego a creer que la cocina de la Familia Ketchup sea desagradable hasta el punto de ser incomestible.",
  ui_story_5079_50790500_100_dialog_content = "¿Estás seguro de que ustedes dos no están exagerando?",
  ui_story_5079_50790500_101_dialog_content = "¡No es una cuestión de gusto en absoluto! ¿Por qué diablos pondrían zanahorias en la sopa de tomate?",
  ui_story_5079_50790500_102_dialog_content = "¿Zanahorias? Imposible. No guardamos ese tipo de ingredientes en nuestras despensas.",
  ui_story_5079_50790500_103_dialog_content = "¡También soy testigo aquí! ¡Pruébelo por usted misma, señora!",
  ui_story_5079_50790500_104_dialog_content = "...",
  ui_story_5079_50790500_105_dialog_content = "Muy bien entonces...",
  ui_story_5079_50790500_106_dialog_content = "*sorbe*",
  ui_story_5079_50790500_107_dialog_content = "...",
  ui_story_5079_50790500_108_dialog_content = "Por favor acepta mis más sinceras disculpas. Esto no es simplemente sopa de tomate con zanahorias.",
  ui_story_5079_50790500_109_dialog_content = "De hecho, esta sopa sabe como si estuviera hecha completamente de zanahorias.",
  ui_story_5079_50790500_110_dialog_content = "<color=#e8d9bb>¡Blegh! ¡Blegh!</color>",
  ui_story_5079_50790500_111_dialog_content = "¿Qué es ese ruido?",
  ui_story_5079_50790500_112_dialog_content = "Suena como si hubiera bastante conmoción afuera...",
  ui_story_5079_50790500_113_dialog_content = "...",
  ui_story_5079_50790500_114_dialog_content = "...",
  ui_story_5079_50790500_115_dialog_content = "...",
  ui_story_5079_50790500_116_dialog_content = "Por qué...",
  ui_story_5079_50790500_117_dialog_content = "<size=50>¿Por qué ahora todo sabe a zanahorias?</size>",
  ui_story_5079_50790601_1_dialog_content = "Explica la situación actual.",
  ui_story_5079_50790601_2_dialog_content = "Hay una ligera... o más bien una severa perturbación en la ciudad...",
  ui_story_5079_50790601_3_dialog_content = "De repente, y por razones aún desconocidas, toda la comida en Folta ahora sabe a zanahorias, incluso las rocas y el polvo no se salvaron.",
  ui_story_5079_50790601_4_dialog_content = "¿Tenemos alguna pista sobre este fenómeno?",
  ui_story_5079_50790601_5_dialog_content = "La mayoría de los habitantes del pueblo aún están en estado de pánico, lo que dificulta obtener cualquier información significativa.",
  ui_story_5079_50790601_6_dialog_content = "Sin embargo, algunos rumores han comenzado a surgir. Desafortunadamente... mencionarlos aquí sería algo incómodo.",
  ui_story_5079_50790601_7_dialog_content = "No importa eso, por favor comparte tus hallazgos con nosotros.",
  ui_story_5079_50790601_8_dialog_content = "Algunos creen que esto es obra de la tienda de zanahorias. Después de todo, esa es la única tienda que vende zanahorias aquí en Folta.",
  ui_story_5079_50790601_9_dialog_content = "Para empeorar las cosas, la tienda está actualmente cerrada y su dueño no se encuentra por ninguna parte.",
  ui_story_5079_50790601_10_dialog_content = "Varios residentes encontraron demasiado extraño para ser una coincidencia, por lo que formaron un grupo de búsqueda e intentaron buscar al dueño de la tienda y a su familia para descubrir la verdad detrás de todo esto.",
  ui_story_5079_50790601_11_dialog_content = "Entonces parece que debemos localizar al padre de Popo antes que ellos... Dime, ¿hemos descubierto algo relacionado con su paradero?",
  ui_story_5079_50790601_12_dialog_content = "Todavía no, mi señora. Ya he intentado ponerme en contacto con el conductor.",
  ui_story_5079_50790601_13_dialog_content = "Perdóname... Pero él todavía se niega a recibir cualquiera de tus mensajes.",
  ui_story_5079_50790601_14_dialog_content = "¿Ha pasado casi un siglo y todavía me está ignorando?",
  ui_story_5079_50790601_15_dialog_content = "Es tan irritante como siempre, ya veo.",
  ui_story_5079_50790601_16_dialog_content = "Entonces nuestras únicas posibles pistas ahora mismo...",
  ui_story_5079_50790601_17_dialog_content = "¿Eh? No tengo idea de lo que está pasando, ¡pero juro que no hice nada!",
  ui_story_5079_50790601_18_dialog_content = "Lo vio justo ahora, señora. ¡Incluso un solo bocado de zanahoria es demasiado para mí!",
  ui_story_5079_50790601_19_dialog_content = "Entonces, ¿por qué me molestaría en hacer que todo en la ciudad tenga su sabor?",
  ui_story_5079_50790601_20_dialog_content = "Puedo dar fe de su historia. Popo estuvo conmigo todo este tiempo y no tuvo tiempo para hacer algo así.",
  ui_story_5079_50790601_21_dialog_content = "Tenga la seguridad, Popo, no tengo dudas sobre ti.",
  ui_story_5079_50790601_22_dialog_content = "Tu padre, por otro lado... Perdóname, pero—",
  ui_story_5079_50790601_23_dialog_content = "¡Mi padre es un comerciante perfectamente honesto!",
  ui_story_5079_50790601_24_dialog_content = "Además, él está buscando por mí en este momento porque piensa que hui de casa. ¡Él nunca haría algo tan terrible!",
  ui_story_5079_50790601_25_dialog_content = "Pero.",
  ui_story_5079_50790601_26_dialog_content = "No hay necesidad de decir más. Estoy plenamente consciente de la situación de su padre.",
  ui_story_5079_50790601_27_dialog_content = "Dudar de él es dudar de la veracidad de mi propia información. ¿Tienes alguna otra pista?",
  ui_story_5079_50790601_28_dialog_content = "Si él es tan inocente como crees que es, entonces solo hay otra posibilidad...",
  ui_story_5079_50790601_29_dialog_content = "Nuestros informes indican que solo un forastero está visitando Folta hoy y que su llegada coincide en gran medida con los extraños sucesos en nuestro pueblo.",
  ui_story_5079_50790601_30_dialog_content = "Algunos residentes creen firmemente que este forastero tiene las respuestas que buscan.",
  ui_story_5079_50790601_31_dialog_content = "...",
  ui_story_5079_50790601_32_dialog_content = "...",
  ui_story_5079_50790601_33_dialog_content = "Espera, ¿por qué me miras así?",
  ui_story_5079_50790601_34_dialog_content = "Esa cosa detrás de ti parece contener un gran poder.",
  ui_story_5079_50790601_35_dialog_content = "Por favor, perdóname... May ¿Puedo echar un vistazo más de cerca para así May descartar cualquier sospecha sobre ti?",
  ui_story_5079_50790601_36_dialog_content = "!",
  ui_story_5079_50790601_37_dialog_content = "No te atrevas a acercarte a mi Piedra Cazadora.",
  ui_story_5079_50790601_38_dialog_content = "Ya te lo dije, vine a Folta para comprar ingredientes para un banquete. ¿Cómo me beneficiaría en absoluto que todo supiera a zanahorias?",
  ui_story_5079_50790601_39_dialog_content = "Debes disculpar mi rudeza... Pero la verdad solo se revelará a través de un cuidadoso examen.",
  ui_story_5079_50790601_40_dialog_content = "Humph, ¿esto es lo que la Familia Ketchup llama \"hospitalidad\"?",
  ui_story_5079_50790601_41_dialog_content = "Si es así, déjame advertirte: ¡Yo tampoco soy alguien a quien quieras molestar!",
  ui_story_5079_50790700_1_dialog_content = "Las cosas se salieron un poco de control hace un momento. ¿Pero acusarme sin pruebas e incluso atacarme? Ya no podía soportarlo más.",
  ui_story_5079_50790700_2_dialog_content = "Ese chico no te lastimó, ¿verdad? ¿Hunting Stone?",
  ui_story_5079_50790700_3_dialog_content = "...",
  ui_story_5079_50790700_4_dialog_content = "<color=#e8d9bb>*pasos*</color>",
  ui_story_5079_50790700_5_dialog_content = "Se pusieron al día rápidamente, ¿no es así? ¡Prepárate, Piedra de Caza!",
  ui_story_5079_50790700_6_dialog_content = "¡Ahh!",
  ui_story_5079_50790700_7_dialog_content = "Oh, es solo Popo. Puedes relajarte ahora, Piedra de Caza.",
  ui_story_5079_50790700_8_dialog_content = "...",
  ui_story_5079_50790700_9_dialog_content = "¿Qué... Qué has hecho?",
  ui_story_5079_50790700_10_dialog_content = "No fue mi intención dejarte atrás, pero esas personas eran—",
  ui_story_5079_50790700_11_dialog_content = "¡Estabas tan genial hace un momento!",
  ui_story_5079_50790700_12_dialog_content = "¿Decir ah?",
  ui_story_5079_50790700_13_dialog_content = "¡Te enfrentaste a toda la Familia Ketchup tú solo! Ni siquiera podría soñar con hacer algo así!",
  ui_story_5079_50790700_14_dialog_content = "¡Especialmente ese asesor! ¡Siempre he estado aterrado de ese tipo!",
  ui_story_5079_50790700_15_dialog_content = "Oh, ¿te refieres a ese tipo extrañamente educado que siempre se disculpa?",
  ui_story_5079_50790700_16_dialog_content = "No fue tan educado cuando nos amenazó antes... Pero no pensé que realmente llegaríamos a los golpes después.",
  ui_story_5079_50790700_17_dialog_content = "Aun así, se sintió bien poner a ese raro arrepentido en su lugar. Siento que hice algo similar antes...",
  ui_story_5079_50790700_18_dialog_content = "¿Qué me pasa hoy? Es como si en cada lugar al que me giro, sigo sintiendo un deja vu...",
  ui_story_5079_50790700_19_dialog_content = "¿Puedo preguntarte algo? ¿Por qué no intentaste simplemente explicarte a ellos?",
  ui_story_5079_50790700_20_dialog_content = "Claramente no somos los culpables aquí, ¡e incluso la Familia Ketchup tiene que escuchar la razón! ¿Por qué escoger una pelea sin sentido con ellos en su lugar?",
  ui_story_5079_50790700_21_dialog_content = "Dijiste que no tiene sentido, ¿realmente crees que explicar las cosas habría hecho alguna diferencia?",
  ui_story_5079_50790700_22_dialog_content = "He intentado hacer eso desde que era niño... pero nadie nunca escucha. Por eso ya no me molesto.",
  ui_story_5079_50790700_23_dialog_content = "P-Pero... Escuché a alguien decir que la Familia Ketchup ya ha emitido una orden para tu arresto!",
  ui_story_5079_50790700_24_dialog_content = "¿Arrestar?",
  ui_story_5079_50790700_25_dialog_content = "Aunque parecías totalmente genial mientras luchabas contra la Familia Ketchup... Cuanto más luches, más van a sospechar de ti.",
  ui_story_5079_50790700_26_dialog_content = "¿Qué tal esto? ¿Por qué no les dices que Hunting Stone solo atacó porque quería protegerte, y que en realidad no querías pelear?",
  ui_story_5079_50790700_27_dialog_content = "...",
  ui_story_5079_50790700_28_dialog_content = "Es cierto que la Piedra de Caza tiene voluntad propia, y que mi poder proviene de ella...",
  ui_story_5079_50790700_29_dialog_content = "Pero todo lo que acaba de suceder fue mi culpa. No estoy a punto de echar la culpa a nadie ni a nada más.",
  ui_story_5079_50790700_30_dialog_content = "!",
  ui_story_5079_50790700_31_dialog_content = "Oh... Ya veo. Debes ser muy buen amigo de Hunting Stone. Honestamente, estoy un poco celoso.",
  ui_story_5079_50790700_32_dialog_content = "... ¿Amigos? No podrías estar más equivocado.",
  ui_story_5079_50790700_33_dialog_content = "Puede ser algo útil en una pelea, pero en la vida cotidiana, no me trae más que problemas innecesarios.",
  ui_story_5079_50790700_34_dialog_content = "¿Quién querría que esta cosa extraña los siguiera todo el tiempo, o la llamara \"amigo\", para el caso?",
  ui_story_5079_50790700_35_dialog_content = "¡Guau... Eso suena como el amigo más leal para mí! ¡Alguien que siempre está a tu lado y nunca te abandona!",
  ui_story_5079_50790700_36_dialog_content = "¡Vale, ahora estoy extremadamente celoso!",
  ui_story_5079_50790700_37_dialog_content = "¿No escuchas nunca lo que la gente te dice?",
  ui_story_5079_50790700_38_dialog_content = "¡Incluso te entiende a ti también! ¡Siempre que estés listo para luchar, entra en acción!",
  ui_story_5079_50790700_39_dialog_content = "Si no lo quieres, ¿por qué no me lo dejas a mí en su lugar?",
  ui_story_5079_50790700_40_dialog_content = "Eh... ¿O tal vez no? ¡Después de todo, no querría arruinar la amistad entre ustedes!",
  ui_story_5079_50790700_41_dialog_content = "Si no puedes dármelo, ¿podría pedírtelo prestado alguna vez? ¿Por favor? ¿Por favor?",
  ui_story_5079_50790700_42_dialog_content = "...",
  ui_story_5079_50790700_43_dialog_content = "...",
  ui_story_5079_50790700_44_dialog_content = "Lo viste en la batalla hace un momento... ¿No tienes miedo de que pueda lastimarte?",
  ui_story_5079_50790700_45_dialog_content = "¿Ah?",
  ui_story_5079_50790700_46_dialog_content = "Además, solo nos conocemos desde hace menos de un día. ¿Por qué estás tan dispuesto a confiar en mí?",
  ui_story_5079_50790700_47_dialog_content = "¿Alguna vez te has planteado que estoy evitando la investigación de la Familia Ketchup porque en realidad soy culpable?",
  ui_story_5079_50790700_48_dialog_content = "Bueno... Supongo que es porque hemos estado juntos todo este tiempo.",
  ui_story_5079_50790700_49_dialog_content = "¡Estoy seguro de que eres una buena persona! ¡Mi sexto sentido me lo dice!",
  ui_story_5079_50790700_50_dialog_content = "Eso no es todo, ¿verdad? Lo siento, Popo, pero no eres exactamente el mejor ocultando tus pensamientos y sentimientos.",
  ui_story_5079_50790700_51_dialog_content = "Que confíes en mí de manera tan incondicional significa que ya tienes a otro sospechoso en mente, ¿verdad?",
  ui_story_5079_50790700_52_dialog_content = "Eso es... Eso es solo parte de la razón, ¡pero sí!",
  ui_story_5079_50790700_53_dialog_content = "La verdad es... creo que mi padre podría ser el responsable de todo esto.",
  ui_story_5079_50790700_54_dialog_content = "Las zanahorias fueron la razón por la que tuvimos una pelea tan grande. ¿Quizás está intentando hacer que me gusten las zanahorias haciendo que todo en la ciudad sepa a ellas?",
  ui_story_5079_50790700_55_dialog_content = "¿Pero realmente iría tan lejos solo para hacerme comer zanahorias? Si es así, ¡está yendo demasiado lejos con eso!",
  ui_story_5079_50790700_56_dialog_content = "Deja de actuar. Puedo decir por tu expresión que en realidad no estás enojado con él.",
  ui_story_5079_50790700_57_dialog_content = "No odias a tu padre en absoluto. Te preocupa él, te preocupa que se haya convertido en el objetivo de la ira del público.",
  ui_story_5079_50790700_58_dialog_content = "¿De qué estás hablando? No me importa nada de eso. Solo siento que soy en parte culpable de nuestra pelea.",
  ui_story_5079_50790700_59_dialog_content = "Debido a mi temperamento, siempre consigo molestar a mi padre y hacerlo enojar...",
  ui_story_5079_50790700_60_dialog_content = "Por eso siento que debería hacer algo por él... Obviamente, eso no significa que vaya a disculparme con él o algo así!",
  ui_story_5079_50790700_61_dialog_content = "Un consejo: ser demasiado terco solo complicará las cosas.",
  ui_story_5079_50790700_62_dialog_content = "¿Eh? Pero tú también eres bastante terco, ¿no?",
  ui_story_5079_50790700_63_dialog_content = "Ahora que lo pienso, ¿tal vez tú y tu papá tuvieron un malentendido similar?",
  ui_story_5079_50790700_64_dialog_content = "¡Podrías aprender una o dos cosas de mí, sabes! Como hacer algo agradable por él en secreto...",
  ui_story_5079_50790700_65_dialog_content = "Apuesto a que eso realmente le gustaría.",
  ui_story_5079_50790700_66_dialog_content = "¿Algo que realmente le gusta, eh? Humph, no creo que pueda lograr algo así en mi vida.",
  ui_story_5079_50790700_67_dialog_content = "Comer zanahorias, deshacerme de la Piedra de Caza, o convertirme en la elegante hija que siempre quiso... Ugh, mejor dejemos de hablar de mis propios asuntos.",
  ui_story_5079_50790700_68_dialog_content = "En este momento, puedo garantizar más o menos... que tu padre no está detrás de este lío.",
  ui_story_5079_50790700_69_dialog_content = "¿Eh? ¿En serio? ¿Así que mi corazonada está completamente equivocada? Espera, ¿no estás simplemente intentando cambiar de tema, verdad?",
  ui_story_5079_50790700_70_dialog_content = "Mi pasado ya no es realmente importante, pero tu familia es algo muy cercano y querido para ti.",
  ui_story_5079_50790700_71_dialog_content = "Así que olvídate de mis problemas por ahora. En cuanto a tu padre, estoy bastante seguro de que lo he resuelto todo—",
  ui_story_5079_50790700_72_dialog_content = "Si ahora todo sabe a zanahorias, solo perjudica los intereses del único comerciante de zanahorias del pueblo. ¿Ya captas la idea?",
  ui_story_5079_50790700_73_dialog_content = "Yo... creo que sí! Mmm... Si ese es el caso...",
  ui_story_5079_50790700_74_dialog_content = "¡Entonces las zanahorias son completamente inútiles ahora, ya que las personas pueden comer lo que quieran y aún así saborearlas!",
  ui_story_5079_50790700_75_dialog_content = "Bingo. No tendría sentido que tu padre hiciera algo tan perjudicial para su negocio.",
  ui_story_5079_50790700_76_dialog_content = "¡Ohhh! Eso... ¡Eso tiene mucho sentido! ¿No serás también detective, verdad?",
  ui_story_5079_50790700_77_dialog_content = "Es solo una simple observación, eso es todo. También eres bastante bueno analizando los hechos, Popo. Algo me dice...",
  ui_story_5079_50790700_78_dialog_content = "Podríamos trabajar juntos bastante bien.",
  ui_story_5079_50790700_79_dialog_content = "¡Jejejeje, lo descubrí hace mucho tiempo!",
  ui_story_5079_50790700_80_dialog_content = "(¿Es por eso que he estado tan dispuesto a quedarme? ¿Porque nuestra forma de pensar es tan similar?)",
  ui_story_5079_50790700_81_dialog_content = "(Nuestras personalidades obstinadas y relaciones con nuestros padres también son bastante similares...)",
  ui_story_5079_50790700_82_dialog_content = "(¿Podría ser que ella es una copia exacta de mí cuando era niña? No, eso no puede ser correcto... Estoy seguro de que era un poco más madura que ella.)",
  ui_story_5079_50790700_83_dialog_content = "Entonces... ¿Podrías ayudarme con algo más?",
  ui_story_5079_50790700_84_dialog_content = "¡Por supuesto! Después de todo, eso es lo que una persona madura haría... ejem, quiero decir sí, ¿qué pasa?",
  ui_story_5079_50790700_85_dialog_content = "¡Yo... Yo creo que puedo oler la fuente del sabor a zanahoria! ¡Como si estuviera conectado a mí de alguna manera!",
  ui_story_5079_50790700_86_dialog_content = "O tal vez es porque odio tanto las zanahorias que soy más sensible a ellas que otras personas.",
  ui_story_5079_50790700_87_dialog_content = "El olor... Parece venir de <color=#FFB400>Bosque de Crema</color>. Está lejos de aquí, y hay una cueva dedicada al Dios de la Comida allí.",
  ui_story_5079_50790700_88_dialog_content = "¿Puedes oler algo que viene de una cueva en el bosque a millas de aquí?",
  ui_story_5079_50790700_89_dialog_content = "¡No! Pero mi padre solía llevarme a jugar a esa cueva todo el tiempo. Si tengo que adivinar, ¡debe haber tomado el tren para ir a buscarme en esa cueva!",
  ui_story_5079_50790700_90_dialog_content = "Si es allí donde está ahora, y algo espeluznante realmente está sucediendo en el bosque...",
  ui_story_5079_50790700_91_dialog_content = "No tienes que seguir intentando ocultarlo. Está claro que estás realmente preocupado por tu padre.",
  ui_story_5079_50790700_92_dialog_content = "¡Está bien, estoy preocupado! Y por eso... Me gustaría pedir prestada tu Piedra Cazadora e ir a rescatarlo!",
  ui_story_5079_50790700_93_dialog_content = "¿Crees que estarás bien por tu cuenta?",
  ui_story_5079_50790700_94_dialog_content = "Oh...",
  ui_story_5079_50790700_95_dialog_content = "Admítelo, estás esperando que me ofrezca a ayudar.",
  ui_story_5079_50790700_96_dialog_content = "Eres el único en quien puedo confiar ahora... ¡Pero ayudarme también te beneficia a ti!",
  ui_story_5079_50790700_97_dialog_content = "¿Vaya? ¿Cómo es eso?",
  ui_story_5079_50790700_98_dialog_content = "Ayudarme a encontrar a mi padre no sería un problema para ti en absoluto, y una vez que lo hagamos, estoy seguro de que él hará todo lo posible para limpiar tu buen nombre.",
  ui_story_5079_50790700_99_dialog_content = "Y si logras eliminar el sabor de la zanahoria para el pueblo, reunir tus ingredientes solo será mucho más fácil, ¿verdad?",
  ui_story_5079_50790700_100_dialog_content = "Lo sabía...",
  ui_story_5079_50790700_101_dialog_content = "¿Eh? ¿Sabías qué?",
  ui_story_5079_50790700_102_dialog_content = "Nada. Simplemente me impresionas a veces, eso es todo.",
  ui_story_5079_50790700_103_dialog_content = "Te ayudaré, pero no porque me hayas persuadido o algo así. Nuestros pensamientos simplemente coinciden.",
  ui_story_5079_50790700_104_dialog_content = "¿En serio? ¿En serio? ¡Entonces tal vez también tengo algo de potencial de detective en mí!",
  ui_story_5079_50790700_105_dialog_content = "Definitivamente es un talento que vale la pena entrenar. Tal vez te presentaré algunas de mis reglas favoritas algún día.",
  ui_story_5079_50790700_106_dialog_content = "¿Reglas?",
  ui_story_5079_50790700_107_dialog_content = "¿Interesado? Te contaré todo sobre ellos cuando tengamos algo de tiempo libre, pero ahora mismo...",
  ui_story_5079_50790700_108_dialog_content = "¡Vamos al bosque!",
  ui_story_5079_50790700_109_dialog_content = "¡Bien! ¡Vamos!",
  ui_story_5079_50790801_1_dialog_content = "Urgh... El olor aquí fuera es horrible. Definitivamente viene de un lugar...",
  ui_story_5079_50790801_2_dialog_content = "¿Podría ser la cueva del Dios de la Comida?",
  ui_story_5079_50790801_3_dialog_content = "Hablando de eso, ¿crees que este dios está involucrado de alguna manera?",
  ui_story_5079_50790801_4_dialog_content = "Preferiría no hablar de eso. Después de todo, el Dios de la Comida es la deidad más venerada de Folta.",
  ui_story_5079_50790801_5_dialog_content = "Hacemos ofrendas regulares y, a cambio, el Dios de la Comida concede nuestros deseos más sinceros.",
  ui_story_5079_50790801_6_dialog_content = "¿Es por eso que sospechaste de tu padre antes? ¿Porque crees que podría haber ido al Dios de la Comida y deseado que todo supiera a zanahorias?",
  ui_story_5079_50790801_7_dialog_content = "Sí...",
  ui_story_5079_50790801_8_dialog_content = "¿Este Dios de la Comida realmente puede hacer que un deseo como ese se haga realidad?",
  ui_story_5079_50790801_9_dialog_content = "¡Por supuesto! La Familia Ketchup recibió su sagrado Libro de Cocina Negro del Dios de la Comida.",
  ui_story_5079_50790801_10_dialog_content = "Esa familia ha estado en el poder durante generaciones gracias al conocimiento encontrado en ese libro.",
  ui_story_5079_50790801_11_dialog_content = "De repente, algo se siente mal...",
  ui_story_5079_50790801_12_dialog_content = "No me digas que hay alguien con un maletín blanco lleno de ingredientes que se mantiene cerca del jefe de la Familia Ketchup.",
  ui_story_5079_50790801_13_dialog_content = "Yo... Yo creo que sí? Espera, ¿esto significa que ya has investigado a la Familia Ketchup?",
  ui_story_5079_50790801_14_dialog_content = "Para nada, pero algo acerca de toda la Familia Ketchup me hace sentir... ¿nostálgico?",
  ui_story_5079_50790801_15_dialog_content = "Eso no es importante ahora... Lo importante es encontrar una manera de llegar a ese bosque.",
  ui_story_5079_50790801_16_dialog_content = "La forma más rápida de llegar al Bosque Crema es en tren, pero...",
  ui_story_5079_50790801_17_dialog_content = "¿Tampoco hay señales de ellos aquí? Ustedes, hombres, busquen en esa área.",
  ui_story_5079_50790801_18_dialog_content = "¡Sí señor!",
  ui_story_5079_50790801_19_dialog_content = "La calle está llena de gente que te está buscando justo ahora...",
  ui_story_5079_50790801_20_dialog_content = "Urgh, qué fastidio. Si mi misión no fuera tan importante, iría a limpiar el suelo con ese raro una vez más.",
  ui_story_5079_50790801_21_dialog_content = "Escucha, Popo. Si me encuentran y no puedo evitar una pelea, necesitas tomar la Piedra Cazadora e ir directamente al bosque.",
  ui_story_5079_50790801_22_dialog_content = "¡De ninguna manera, nunca podría dejarte atrás! Somos los socios perfectos ahora, ¿recuerdas?",
  ui_story_5079_50790801_23_dialog_content = "¡Incluso escogí un nombre para nosotros! ¡\"El Equipo de Sueño Anti-Zanahoria\"!",
  ui_story_5079_50790801_24_dialog_content = "¿Es eso realmente lo mejor que se te ocurrió? ¿No puedes al menos intentar—",
  ui_story_5079_50790801_25_dialog_content = "<color=#828282>¡Whoosh!</color>",
  ui_story_5079_50790801_26_dialog_content = "¡Cuidado, Popo!",
  ui_story_5079_50790801_27_dialog_content = "¿Ah?",
  ui_story_5079_50790801_28_dialog_content = "!",
  ui_story_5079_50790801_29_dialog_content = "Uf... Eso estuvo cerca.",
  ui_story_5079_50790801_30_dialog_content = "Ahora bien... ¿Alguien puede decirme por qué un montón de frutas y verduras están volando por el aire?",
  ui_story_5079_50790801_31_dialog_content = "Quédate detrás de la Piedra de Caza, Popo. No te acerques demasiado.",
  ui_story_5079_50790801_32_dialog_content = "V-Vale... Pero ¿qué está pasando por aquí?",
  ui_story_5079_50790801_33_dialog_content = "...",
  ui_story_5079_50790801_34_dialog_content = "¡Alto! ¿Qué crees que estás haciendo? ¿Son topos o qué? ¿Por qué intentan arruinar el delicioso sabor de las zanahorias?",
  ui_story_5079_50790801_35_dialog_content = "¡Solo queremos que todo sepa como se supone que debe saber!",
  ui_story_5079_50790801_36_dialog_content = "¡Rápido, espolvorea un poco más de sal y bicarbonato de sodio sobre todo! ¡Cuanto más, mejor!",
  ui_story_5079_50790801_37_dialog_content = "¡Para! Este tiene que ser el próximo paso de la naturaleza en la evolución. ¡No te dejaremos interferir con la voluntad del Dios de la Comida!",
  ui_story_5079_50790801_38_dialog_content = "Además, a todos ustedes les gustan las zanahorias, ¿no es así? ¿Por qué oponerse a nosotros?",
  ui_story_5079_50790801_39_dialog_content = "¡Yo... Yo me gustan las zanahorias y todo, pero no quiero pasar el resto de mi vida comiéndolas!",
  ui_story_5079_50790801_40_dialog_content = "¡Lo lamento!",
  ui_story_5079_50790801_41_dialog_content = "¡Para! ¡Detente ahora mismo!",
  ui_story_5079_50790801_42_dialog_content = "¡Por un mundo perfecto y lleno de zanahorias! ¡A la carga!",
  ui_story_5079_50790801_43_dialog_content = "¡Por Folta y su orgullosa diversidad culinaria! ¡Espolvorea!",
  ui_story_5079_50790801_44_dialog_content = "Vaya... Todo el pueblo se ha vuelto loco, ¿no es así?",
  ui_story_5079_50790801_45_dialog_content = "Ya se han destruido tantos edificios. A este ritmo, Folta ya no será la misma ciudad...",
  ui_story_5079_50790801_46_dialog_content = "Y mi misión será tan buena como fallida. Urgh, qué dolor...",
  ui_story_5079_50790801_47_dialog_content = "Nada me molesta más que este tipo de caos y desorden.",
  ui_story_5079_50790801_48_dialog_content = "...",
  ui_story_5079_50790801_49_dialog_content = "¡Mira! ¡La Piedra de Caza se está moviendo!",
  ui_story_5079_50790801_50_dialog_content = "¡Oye! ¡No nos causes más problemas metiéndote en la pelea!",
  ui_story_5079_50790801_51_dialog_content = "No espera, parece que Hunting Stone está tratando de guiarnos por este camino.",
  ui_story_5079_50790801_52_dialog_content = "... ¿Es eso así?",
  ui_story_5079_50790801_53_dialog_content = "Oye, no pienses que te voy a seguir solo porque tú quieras.",
  ui_story_5079_50790801_54_dialog_content = "...",
  ui_story_5079_50790801_55_dialog_content = "¿Y ahora no quieres que te alcance? No creas que puedes correr más que yo, ¡rueda podrida!",
  ui_story_5079_50790801_56_dialog_content = "Vamos, Popo.",
  ui_story_5079_50790801_57_dialog_content = "<size=30>¿Por qué se está poniendo tan nerviosa? Supongo que después de todo es bastante inmadura...</size>",
  ui_story_5079_50790801_58_dialog_content = "¿Qué fue eso?",
  ui_story_5079_50790801_59_dialog_content = "¡Nada! ¡Ya voy!",
  ui_story_5079_50790801_60_dialog_content = "¿Quieres que pasemos por aquí? Bueno, es la estación de tren.",
  ui_story_5079_50790801_61_dialog_content = "Bien hecho, Hunting Stone.",
  ui_story_5079_50790801_62_dialog_content = "!",
  ui_story_5079_50790801_63_dialog_content = "Pero no te llenes demasiado de ti mismo. Si terminas asustando a alguien en el tren de nuevo...",
  ui_story_5079_50790801_64_dialog_content = "Retiro mi cumplido.",
  ui_story_5079_50790801_65_dialog_content = "¿Podrías darte prisa? ¡No quiero perder el tren dos veces en un día!",
  ui_story_5079_50790801_66_dialog_content = "Oye, ten cuidado...",
  ui_story_5079_50790801_67_dialog_content = "<color=#e8d9bb>¡Wham!</color>",
  ui_story_5079_50790801_68_dialog_content = "Bueno, al menos logró encontrarse con alguien dos veces hoy...",
  ui_story_5079_50790801_69_dialog_content = "Ay...",
  ui_story_5079_50790801_70_dialog_content = "¿Eh? ¿Eres tú, Popo?",
  ui_story_5079_50790801_71_dialog_content = "¡Uh-oh!",
  ui_story_5079_50790801_72_dialog_content = "Todos en Folta han perdido la cabeza con este asunto de las zanahorias.",
  ui_story_5079_50790801_73_dialog_content = "Como la hija del único comerciante de zanahorias en la ciudad, deberías ser más cuidadosa aquí.",
  ui_story_5079_50790801_74_dialog_content = "Eh... Está bien, pero...",
  ui_story_5079_50790801_75_dialog_content = "Aquí, te escoltaré de regreso.",
  ui_story_5079_50790801_76_dialog_content = "P-Pero tengo que coger el tren.",
  ui_story_5079_50790801_77_dialog_content = "¿El tren? ¿Te refieres al que va al Bosque de Crema? Espera un minuto...",
  ui_story_5079_50790801_78_dialog_content = "¿Quién es esa persona a tu lado? Espera, esa rueda... ¡He oído hablar de ella antes! ¿Podría ser ella...",
  ui_story_5079_50790801_79_dialog_content = "Ahórrenos ya las teatralidades. Sí, soy yo, el malvado intruso de fuera de la ciudad. ¿Contentos ahora?",
  ui_story_5079_50790801_80_dialog_content = "Adelante y sube al tren, Popo. Yo me encargaré de las cosas desde aquí.",
  ui_story_5079_50790901_1_dialog_content = "¡E-Espera, para! ¡Ambos de ustedes!",
  ui_story_5079_50790901_2_dialog_content = "...",
  ui_story_5079_50790901_3_dialog_content = "...",
  ui_story_5079_50790901_4_dialog_content = "¡Te conozco! Eres uno de los habituales de nuestra tienda, ¿verdad?",
  ui_story_5079_50790901_5_dialog_content = "¡Amas las zanahorias, por eso estás luchando para mantener las cosas como están ahora! ¿Verdad? ¿Verdad?",
  ui_story_5079_50790901_6_dialog_content = "Sí... Sabía que la hija de nuestro gran comerciante de zanahorias lo entendería.",
  ui_story_5079_50790901_7_dialog_content = "¡Entonces no hay razón para que peleemos! ¿Sabes por qué la Familia Ketchup está tras mi amigo aquí, verdad?",
  ui_story_5079_50790901_8_dialog_content = "... ¿Esto significa que los rumores son ciertos?",
  ui_story_5079_50790901_9_dialog_content = "No exactamente, no. Ella es una detective y me está ayudando a buscar a mi papá en este momento.",
  ui_story_5079_50790901_10_dialog_content = "Ejem... Pactlock Holmes, a su servicio.",
  ui_story_5079_50790901_11_dialog_content = "Ya veo, ya veo. Ya seas un detective real o no, ¡te debemos nuestro agradecimiento!",
  ui_story_5079_50790901_12_dialog_content = "De hecho, nos sentiríamos honrados si sirvieras como la Santa de las Zanahorias de nuestra organización!",
  ui_story_5079_50790901_13_dialog_content = "No gracias, pero si realmente quieres expresar tu gratitud...",
  ui_story_5079_50790901_14_dialog_content = "Necesito subirme a ese tren, pero no estoy seguro de cómo está la estación ahora mismo. ¿Crees que puedes darme algo de cobertura?",
  ui_story_5079_50790901_15_dialog_content = "¡Por supuesto! Si no me equivoco, la persona que vende boletos de tren pertenece a la facción enemiga.",
  ui_story_5079_50790901_16_dialog_content = "¡Me aseguraré de que ninguno de ellos logre verte!",
  ui_story_5079_50790901_17_dialog_content = "Allí, ¡ahora es tu oportunidad! Mi gente ha captado su atención, y pronto debería estallar una pelea...",
  ui_story_5079_50790901_18_dialog_content = "¡Dirígete a la estación lo más rápido que puedas!",
  ui_story_5079_50790901_19_dialog_content = "Gracias... Pero, ¿por qué tú y tu gente están dispuestos a llegar tan lejos solo por las zanahorias?",
  ui_story_5079_50790901_20_dialog_content = "¡Naturalmente, es porque ni siquiera podemos comenzar a describir nuestro amor por las zanahorias!",
  ui_story_5079_50790901_21_dialog_content = "Crujientes y dulces, tienen una textura maravillosa. ¡Podrías comer cien zanahorias sin cansarte de ellas!",
  ui_story_5079_50790901_22_dialog_content = "¡También son una excelente fuente de energía y nutrición! Pueden promover el crecimiento y desarrollo de los huesos, mejorar la tez e incluso aliviar la fatiga ocular!",
  ui_story_5079_50790901_23_dialog_content = "Pero lo más importante, ¡estas magníficas verduras pueden tratar el estreñimiento! ¡Esos que odian las zanahorias deben estar muy confundidos al respecto en este momento!",
  ui_story_5079_50790901_24_dialog_content = "... ¿E-Es eso así?",
  ui_story_5079_50790901_25_dialog_content = "<size=30>No tenía idea de que las zanahorias tuvieran tantas buenas cualidades.</size>",
  ui_story_5079_50790901_26_dialog_content = "Pero ¿por qué preguntas, santa Zanahoria? A menos que... ¡Ah, ya veo!",
  ui_story_5079_50790901_27_dialog_content = "¿Estabas probando mi devoción por la todopoderosa zanahoria justo ahora, verdad? Descansa tranquila, mi santa, ¡siempre estaré del lado de la bondad de la zanahoria!",
  ui_story_5079_50790901_28_dialog_content = "Uh... Está bien entonces. Respeto tu decisión.",
  ui_story_5079_50790901_29_dialog_content = "Deberíamos ponernos en marcha, Popo.",
  ui_story_5079_50790901_30_dialog_content = "Solo un momento. ¿También vas con ella, Popo?",
  ui_story_5079_50790901_31_dialog_content = "Sí, por supuesto. ¿Es eso un problema?",
  ui_story_5079_50790901_32_dialog_content = "Nuestros enemigos pueden tener ojos fuera de la ciudad. Puede que no reconozcan a la Santa de la Zanahoria, pero definitivamente te reconocerán a ti.",
  ui_story_5079_50790901_33_dialog_content = "¡Sería peligroso para ti ir solo!",
  ui_story_5079_50790901_34_dialog_content = "Es cierto... Podría ser mejor que te quedes aquí, Popo. Estoy seguro de que los habituales de tu tienda te cuidarán bien.",
  ui_story_5079_50790901_35_dialog_content = "Pero... Pero quiero ayudarte—",
  ui_story_5079_50790901_36_dialog_content = "Descansa tranquilo, mi gente y yo haremos todo lo que esté a nuestro alcance para proteger a la Princesa Popo.",
  ui_story_5079_50790901_37_dialog_content = "¿P-Princesa?",
  ui_story_5079_50790901_38_dialog_content = "Estarás bien, Popo. ¿Recuerdas cómo querías pedir prestada la Piedra Cazadora antes?",
  ui_story_5079_50790901_39_dialog_content = "Como le agradas tanto, estoy seguro de que no le importará quedarse a tu lado. De esa manera, no tendrás nada de qué preocuparte, ¿verdad?",
  ui_story_5079_50790901_40_dialog_content = "Pero entonces... ¿No hará eso las cosas más peligrosas para ti?",
  ui_story_5079_50790901_41_dialog_content = "¿Yo? ¿Estás bromeando? Me sentiría mucho mejor sin que Hunting Stone me siguiera a todas partes.",
  ui_story_5079_50790901_42_dialog_content = "Además, ahora eres amigo de él, ¿verdad? Incluso puedes entender sus sentimientos.",
  ui_story_5079_50790901_43_dialog_content = "Y realmente parece querer quedarse contigo...",
  ui_story_5079_50790901_44_dialog_content = "?",
  ui_story_5079_50790901_45_dialog_content = "Si fuera cualquier otra persona, volvería a mí de inmediato.",
  ui_story_5079_50790901_46_dialog_content = "¿Eso significa... que soy especial?",
  ui_story_5079_50790901_47_dialog_content = "Parece que sí. Así que solo quédate aquí y espérame, ¿de acuerdo?",
  ui_story_5079_50790901_48_dialog_content = "O-Okay... Haré exactamente lo que me pediste. ¿No es así, Piedra de Caza?",
  ui_story_5079_50790901_49_dialog_content = "!",
  ui_story_5079_50790901_50_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790901_51_dialog_content = "¡Atención por favor, a todos! Es un honor para mí presentarles a todos a la Princesa Popo, hija de nuestro venerable comerciante de zanahorias del pueblo!",
  ui_story_5079_50790901_52_dialog_content = "¡Bienvenidos!",
  ui_story_5079_50790901_53_dialog_content = "H-Hola, a todos.",
  ui_story_5079_50790901_54_dialog_content = "Para que te sientas más en casa, ¡he preparado un pastel muy especial solo para ti! Por favor disfruta, Princesa Popo!",
  ui_story_5079_50790901_55_dialog_content = "¡Por favor, disfruta!",
  ui_story_5079_50790901_56_dialog_content = "¡Pasé mi sangre, sudor y lágrimas horneando este pastel para ti! Incluso agregué zanahorias trituradas a la crema...",
  ui_story_5079_50790901_57_dialog_content = "¡Por supuesto, solo utilicé las zanahorias más frescas y de mejor calidad de la tienda de tu papá!",
  ui_story_5079_50790901_58_dialog_content = "Aunque parezca algo redundante hornear un pastel de zanahoria para la hija de un comerciante de zanahorias, espero que lo disfrutes de todos modos.",
  ui_story_5079_50790901_59_dialog_content = "¡Nosotros también lo esperamos!",
  ui_story_5079_50790901_60_dialog_content = "Bueno.",
  ui_story_5079_50790901_61_dialog_content = "Por favor disfruta, princesa.",
  ui_story_5079_50790901_62_dialog_content = "¿P-Puedo comerlo en un lugar agradable y tranquilo? No estoy acostumbrado a comer frente a tanta gente...",
  ui_story_5079_50790901_63_dialog_content = "¡Por supuesto, princesa! Pero si puedo preguntar, ¿por qué te ves tan mareada?",
  ui_story_5079_50790901_64_dialog_content = "¿Podría ser que mi pastel de zanahoria no esté a la altura de tus estándares?",
  ui_story_5079_50790901_65_dialog_content = "No eso no es...",
  ui_story_5079_50790901_66_dialog_content = "Ahora que lo pienso, ¿alguien ha visto alguna vez a la hija del comerciante de zanahorias comer una zanahoria?",
  ui_story_5079_50790901_67_dialog_content = "No, pero la vi discutir con su padre una vez, y parecía que las zanahorias eran la razón detrás de su pelea...",
  ui_story_5079_50790901_68_dialog_content = "?",
  ui_story_5079_50790901_69_dialog_content = "¡Yo... Yo amo las zanahorias! Simplemente no me has visto comerlas, eso es todo... ¿V-Ves? S-Son deliciosas...",
  ui_story_5079_50790901_70_dialog_content = "Urgh... Blegh...",
  ui_story_5079_50790901_71_dialog_content = "¿De verdad te estás pellizcando la nariz ahora mismo?",
  ui_story_5079_50790901_72_dialog_content = "¡T-Tú no entiendes! Esta es la mejor manera de experimentar el sabor de las zanahorias—",
  ui_story_5079_50790901_73_dialog_content = "<size=45>Pffffft—</size>",
  ui_story_5079_50790901_74_dialog_content = "...",
  ui_story_5079_50790901_75_dialog_content = "...",
  ui_story_5079_50790901_76_dialog_content = "...",
  ui_story_5079_50790901_77_dialog_content = "No te gustan las zanahorias en absoluto, ¿verdad? No eres nuestra princesa, sino nuestro enemigo jurado!",
  ui_story_5079_50790901_78_dialog_content = "Tu amigo fue al Bosque Crema para buscar a tu padre, ¿verdad?",
  ui_story_5079_50790901_79_dialog_content = "¿Qué podría estar haciendo allí fuera? ¿Podría ser que está intentando destruir nuestro hermoso paraíso lleno de zanahorias?",
  ui_story_5079_50790901_80_dialog_content = "¡Rápido! Tenemos que capturar a Popo y obligarla a llevarnos a esa mujer!",
  ui_story_5079_50790901_81_dialog_content = "No... ¡N-No te acerques más!",
  ui_story_5079_50790901_82_dialog_content = "¿Me ayudarás, verdad? ¿Piedra de Caza?",
  ui_story_5079_50790901_83_dialog_content = "!",
  ui_story_5079_50791001_1_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50791001_2_dialog_content = "Un placer volver a verte, milady. Hemos llegado al Bosque de Crema, por favor cuida tu paso al bajar del tren.",
  ui_story_5079_50791001_3_dialog_content = "Oh... ¿Ya estamos aquí? Fue mucho más rápido de lo que esperaba...",
  ui_story_5079_50791001_4_dialog_content = "Las cosas son casi extrañamente aburridas sin un niño molesto o una rueda pegajosa siguiéndote.",
  ui_story_5079_50791001_5_dialog_content = "Fue realmente un viaje bastante largo, aunque pasaste la mayor parte del tiempo mirando por la ventana.",
  ui_story_5079_50791001_6_dialog_content = "¿Es la inquietud en Folta la fuente de tu estrés? ¿Puedo ser de alguna ayuda?",
  ui_story_5079_50791001_7_dialog_content = "¿Así que estás al tanto de lo que está pasando en el pueblo?",
  ui_story_5079_50791001_8_dialog_content = "No importa eso, tengo algo más importante que preguntar. ¿Has visto al dueño de la tienda de zanahorias últimamente?",
  ui_story_5079_50791001_9_dialog_content = "Por lo que he escuchado, se fue de la ciudad en este tren hoy más temprano.",
  ui_story_5079_50791001_10_dialog_content = "¿El comerciante de zanahorias? Sí, de hecho. Bajó en esta misma estación, y creo que mencionó que iba a la cueva del Dios de la Comida.",
  ui_story_5079_50791001_11_dialog_content = "¿En serio? Parece que Popo tenía razón todo el tiempo.",
  ui_story_5079_50791001_12_dialog_content = "Creo que también tienes una impresión de él.",
  ui_story_5079_50791001_13_dialog_content = "Después de todo, lo conociste cuando llegaste por primera vez a Folta. Fue un encuentro bastante divertido, debo decir.",
  ui_story_5079_50791001_14_dialog_content = "¿Lo conocí? ¿Te refieres a que ese pasajero extremadamente modesto era el padre de Popo?",
  ui_story_5079_50791001_15_dialog_content = "Ugh, todo este lío se podría haber evitado si simplemente lo hubiera detenido de subir al tren en aquel entonces...",
  ui_story_5079_50791001_16_dialog_content = "Parece que tu pregunta ha sido respondida. Por favor, recuerda llevar tu equipaje cuando bajes del tren... Eh, un momento.",
  ui_story_5079_50791001_17_dialog_content = "Perdona, pero ¿finalmente te deshiciste de la Piedra de Caza?",
  ui_story_5079_50791001_18_dialog_content = "Seguramente no lo abandonaste en un rincón oscuro de la ciudad y lo dejaste sufrir en una miserable soledad, ¿verdad?",
  ui_story_5079_50791001_19_dialog_content = "No tienes que hacerlo sonar tan miserable...",
  ui_story_5079_50791001_20_dialog_content = "Acabo de dejarlo con alguien más por el momento.",
  ui_story_5079_50791001_21_dialog_content = "Perdóname, no pude evitar imaginar una escena de inmensa tragedia y soledad justo ahora.",
  ui_story_5079_50791001_22_dialog_content = "Creo que su lugar legítimo está a tu lado, y lo mismo se aplica para ti también.",
  ui_story_5079_50791001_23_dialog_content = "Realmente no necesito tus opiniones sobre nuestra relación... Pero gracias por la información.",
  ui_story_5079_50791001_24_dialog_content = "No pienses nada de eso. Estoy encantado de ayudarte.",
  ui_story_5079_50791001_25_dialog_content = "Hablando de eso, el jefe de la Familia Ketchup también intentó contactarte sobre el padre de Popo.",
  ui_story_5079_50791001_26_dialog_content = "Pero te negaste a responderle... Al principio pensé que eras una persona sin corazón, pero resulta que en realidad eres bastante cálido de corazón.",
  ui_story_5079_50791001_27_dialog_content = "Si la solicitud fuera de ti, mi querido pasajero, habría hecho todo lo posible para ayudarte.",
  ui_story_5079_50791001_28_dialog_content = "Pero me niego a tratar con esa mujer loca en cualquier capacidad. ¡Preferiría pasar toda la eternidad en fría soledad que volver a conectarme con ella!",
  ui_story_5079_50791001_29_dialog_content = "E-entiendo, lo siento si te molesté. Bajaré del tren de inmediato.",
  ui_story_5079_50791001_30_dialog_content = "El olor a zanahorias se hace más y más fuerte...",
  ui_story_5079_50791001_31_dialog_content = "La fuente del problema debería estar por aquí en alguna parte.",
  ui_story_5079_50791001_32_dialog_content = "¡Graaah!",
  ui_story_5079_50791001_33_dialog_content = "¿Q-Qué?",
  ui_story_5079_50791001_34_dialog_content = "¿Qué hacen los Eclipsites en un lugar como este?",
  ui_story_5079_50791001_35_dialog_content = "Sabía que había algo extraño en este olor a zanahoria... ¿El poder del Dios de la Comida está de alguna manera conectado con los Eclipsites?",
  ui_story_5079_50791001_36_dialog_content = "Si es así, Folta está en mucho más peligro de lo que nos dimos cuenta.",
  ui_story_5079_50791001_37_dialog_content = "Necesito evitarlos por ahora y explorar la cueva...",
  ui_story_5079_50791001_38_dialog_content = "¡Graaah!",
  ui_story_5079_50791001_39_dialog_content = "Tsk, cuanto más me acerco a la cueva, más Eclipsites aparecen.",
  ui_story_5079_50791001_40_dialog_content = "Está bien, Hunting Stone, vamos a...",
  ui_story_5079_50791001_41_dialog_content = "No, espera, la Piedra de Caza no está conmigo ahora mismo... ¿Realmente puedo manejar tantos Eclipsites por mi cuenta?",
  ui_story_5079_50791001_42_dialog_content = "... Je.",
  ui_story_5079_50791001_43_dialog_content = "¿Qué pasa, Pact? ¿Cuándo te volviste tan débil?",
  ui_story_5079_50791001_44_dialog_content = "¡Sin la Piedra de Caza, eliminar a estos Eclipsites debería ser mucho más fácil!",
  ui_story_5079_50791001_45_dialog_content = "Ven y búscanos... ¡Quiero decir, a mí! ¡Ven y búscame!",
  ui_story_5079_50791001_46_dialog_content = "<color=#e8d9bb>¡Golpear!</color>",
  ui_story_5079_50791001_47_dialog_content = "...",
  ui_story_5079_50791001_48_dialog_content = "¡Graaah!",
  ui_story_5079_50791001_49_dialog_content = "...¡Unir!",
  ui_story_5079_50791001_50_dialog_content = "¡Graaah!",
  ui_story_5079_50791001_51_dialog_content = "Tsk... Mis ataques fueron mucho más lentos, y lograron liberarse de mis ataduras mucho antes de lo que esperaba.",
  ui_story_5079_50791001_52_dialog_content = "No tendría tantos problemas contra estos Eclipsites ridículamente débiles si tuviera a Hunting Stone conmigo...",
  ui_story_5079_50791001_53_dialog_content = "Esto no puede estar pasando... ¡Realmente estoy empezando a extrañar esa estúpida rueda! Soy un chiste...",
  ui_story_5079_50791001_54_dialog_content = "Debería confiar en mi propia fuerza ahora mismo...",
  ui_story_5079_50791100_1_dialog_content = "Graah—",
  ui_story_5079_50791100_2_dialog_content = "Uf... Esa debería ser la última de ellas.",
  ui_story_5079_50791100_3_dialog_content = "¿Ves? Mis Luminatics aún son lo suficientemente fuertes para derribar a tantos Eclipsites <color=#FFB400>por mi cuenta</color>.",
  ui_story_5079_50791100_4_dialog_content = "Aunque en el pasado, no me agotaba tanto.",
  ui_story_5079_50791100_5_dialog_content = "Piedra de Caza... No la necesito para luchar, pero sí tiene algunos usos...",
  ui_story_5079_50791100_6_dialog_content = "¡Graaah!",
  ui_story_5079_50791100_7_dialog_content = "¡Ay!",
  ui_story_5079_50791100_8_dialog_content = "¡Bajé la guardia! Tengo que—",
  ui_story_5079_50791100_9_dialog_content = "!",
  ui_story_5079_50791100_10_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5079_50791100_11_dialog_content = "¿Piedra Cazadora? ¿Quién te dijo que volvieras a mí? No me digas que tú—",
  ui_story_5079_50791100_12_dialog_content = "¡Ey! ¿Estás bien?",
  ui_story_5079_50791100_13_dialog_content = "¿Popo? Je, claro que estoy bien. Solo dame un segundo para limpiar el resto de estos Eclipsites.",
  ui_story_5079_50791100_14_dialog_content = "¡Prueba el sabor de mis hermosas espinas!",
  ui_story_5079_50791100_15_dialog_content = "<color=#e8d9bb>¡Banco de iglesia! ¡Tortazo!</color>",
  ui_story_5079_50791100_16_dialog_content = "¡Graaah!",
  ui_story_5079_50791100_17_dialog_content = "¡Yo también puedo ayudar! ¡Piedra de Caza!",
  ui_story_5079_50791100_18_dialog_content = "!",
  ui_story_5079_50791100_19_dialog_content = "Graaah...",
  ui_story_5079_50791100_20_dialog_content = "¡Lo hicimos! ¡Lo hicimos! ¡Eliminamos a todos esos desagradables Eclipsites juntos!",
  ui_story_5079_50791100_21_dialog_content = "¡Así es, lo hicimos! Fuiste increíble, Popo. ¡No tenía idea de que podrías usar Luminatics!",
  ui_story_5079_50791100_22_dialog_content = "Eso es porque no podía... al menos no antes.",
  ui_story_5079_50791100_23_dialog_content = "¡Pero estaba tan asustado cuando vi a esos Eclipsites atacarte, y de repente surgió este poder dentro de mí!",
  ui_story_5079_50791100_24_dialog_content = "Honestamente, no puedo creerlo. ¡Apuesto a que mi padre estará tan feliz cuando se entere!",
  ui_story_5079_50791100_25_dialog_content = "S-Sí... Definitivamente...",
  ui_story_5079_50791100_26_dialog_content = "(La fuente del poder de Popo es la misma que la mía, y parece tener mucho potencial...)",
  ui_story_5079_50791100_27_dialog_content = "(¿Es por eso que ella pudo comandar la Piedra de Caza? Pensé que solo se suponía que me obedecía a mí...)",
  ui_story_5079_50791100_28_dialog_content = "¡El olor a zanahorias viene de la cueva del Dios de la Comida! ¡Ahora estoy seguro de ello!",
  ui_story_5079_50791100_29_dialog_content = "También escucho una voz... ¡Me está diciendo que me acerque!",
  ui_story_5079_50791100_30_dialog_content = "¿Una voz? Creo que solo estás ansioso por encontrar a tu padre...",
  ui_story_5079_50791100_31_dialog_content = "Supongo que eso significa que te importa mucho más de lo que admites...",
  ui_story_5079_50791100_32_dialog_content = "De todos modos, ¿no te dije que me esperaras en la ciudad? ¿Qué te hizo venir detrás de mí?",
  ui_story_5079_50791100_33_dialog_content = "Sobre eso... Esos locos amantes de las zanahorias me obligaron a comer su pastel de zanahoria, y terminé escupiéndolo. Fue entonces cuando supe que mi tapadera había sido descubierta.",
  ui_story_5079_50791100_34_dialog_content = "Así que me fui con Hunting Stone, pero no me di cuenta de que era incluso más rápido que un tren. Llegamos aquí en casi nada de tiempo... No estás enojado conmigo, ¿verdad?",
  ui_story_5079_50791100_35_dialog_content = "Por supuesto que no. Si acaso, estoy furioso de que esos adultos intentaran castigarte con algo tan repugnante.",
  ui_story_5079_50791100_36_dialog_content = "¿Verdad? ¿Verdad? ¡No pude tragar ni un solo bocado! Por eso no tuve más opción que venir a buscarte.",
  ui_story_5079_50791100_37_dialog_content = "Lo sabía desde el principio: el Equipo Anti-Zanahoria tiene que permanecer unido sin importar qué!",
  ui_story_5079_50791100_38_dialog_content = "<size=30>Pero solo hay una Piedra de Caza...</size>",
  ui_story_5079_50791100_39_dialog_content = "¿Ah?",
  ui_story_5079_50791100_40_dialog_content = "(Probablemente Popo aún no se ha dado cuenta. Sus Luminatics todavía son demasiado débiles, por lo que tiene que depender de la Piedra de Caza para usarlas...)",
  ui_story_5079_50791100_41_dialog_content = "¿Cuál es el gran problema, Piedra de Caza? Normalmente nunca puedo deshacerme de ti, pero parece que ahora estás bastante apegado a tu nuevo maestro...",
  ui_story_5079_50791100_42_dialog_content = "Ya que la has elegido a ella en lugar de a mí, más te vale cuidarla bien. ¿Entendido?",
  ui_story_5079_50791100_43_dialog_content = "Ya no tienes que seguirme más, así que déjame finalmente disfrutar de un poco de paz y tranquilidad.",
  ui_story_5079_50791100_44_dialog_content = "...",
  ui_story_5079_50791100_45_dialog_content = "¿De qué estás susurrando allí?",
  ui_story_5079_50791100_46_dialog_content = "¡Como miembro del equipo, exijo saber!",
  ui_story_5079_50791100_47_dialog_content = "No te preocupes por eso. Además, tengo mejores noticias para compartir contigo. Hablé con el conductor del tren y dijo que tu padre se bajó del tren aquí.",
  ui_story_5079_50791100_48_dialog_content = "Definitivamente está involucrado en este loco incidente, aunque no estoy exactamente seguro de cómo.",
  ui_story_5079_50791100_49_dialog_content = "¿Podría ser que padre realmente...",
  ui_story_5079_50791100_50_dialog_content = "Entraré al bosque para comprobar las cosas. Tú y la Piedra Cazadora pueden vigilar aquí.",
  ui_story_5079_50791100_51_dialog_content = "¡No va a suceder! Si vas a entrar al bosque, ¡yo también iré!",
  ui_story_5079_50791100_52_dialog_content = "Hay Eclipsites acechando por aquí, y solo habrá más de ellos en el bosque. Dejarte venir sería demasiado peligroso.",
  ui_story_5079_50791100_53_dialog_content = "¡Pero ahora puedo usar Luminatics! ¡Puedo ayudar!",
  ui_story_5079_50791100_54_dialog_content = "Acabas de descubrir tus poderes hoy, ¿verdad? Usarlos para protegerte te llevará todo lo que tienes, y no tendré tiempo para venir a tu rescate...",
  ui_story_5079_50791100_55_dialog_content = "Puedo manejarme bien solo. Se supone que debemos ayudarnos mutuamente, ¡justo como acordamos!",
  ui_story_5079_50791100_56_dialog_content = "Además, ¿no te acabo de salvar de un montón de Eclipsites ahora mismo?",
  ui_story_5079_50791100_57_dialog_content = "...",
  ui_story_5079_50791100_58_dialog_content = "(Todo en lo que podía pensar antes era en deshacerme de la Piedra de Caza, pero después de ver lo cerca que ha llegado a Popo, yo...)",
  ui_story_5079_50791100_59_dialog_content = "Simplemente dilo, no confías en mí en absoluto, ¿verdad?",
  ui_story_5079_50791100_60_dialog_content = "No es que no confíe en ti. Solo me preocupa que tu padre se decepcione si ve tu Luminática a medio hacer en acción.",
  ui_story_5079_50791100_61_dialog_content = "¿Qu-Qué? No puede ser... ¡Papá siempre soñó que algún día aprendería a usar Luminatics!",
  ui_story_5079_50791100_62_dialog_content = "¿En serio? Pero si aprendes Luminatics, sus expectativas solo irán en aumento. No parará hasta que te conviertas en su hija ideal...",
  ui_story_5079_50791100_63_dialog_content = "Pero ¿quién sabe cuándo estará satisfecho? De hecho, incluso podría...",
  ui_story_5079_50791100_64_dialog_content = "...",
  ui_story_5079_50791100_65_dialog_content = "Uh, no es nada. Olvida que dije algo...",
  ui_story_5079_50791100_66_dialog_content = "Yo... No estoy tan emocionado de mostrarle mis Luminatics...",
  ui_story_5079_50791100_67_dialog_content = "No me importa mientras sepa que él está a salvo. Ayudarte con tu misión es mucho más importante.",
  ui_story_5079_50791100_68_dialog_content = "Además, llegaremos más rápido si yo guío el camino. Confía en mí, ¡conozco muchos atajos!",
  ui_story_5079_50791100_69_dialog_content = "¿Atajos? <size=30>Piedra de Caza, asegúrate de que no haya Eclipsites en el camino de Popo.</size>",
  ui_story_5079_50791100_70_dialog_content = "...",
  ui_story_5079_50791100_71_dialog_content = "Tsk, se fue a protegerla sin ninguna vacilación...",
  ui_story_5079_50791100_72_dialog_content = "Bueno, al menos es agradable y tranquilo caminar solo.",
  ui_story_5079_50791100_73_dialog_content = "Mientras me ayude a completar mi misión... Supongo que puedo seguir por ahora.",
  ui_story_5079_50791100_74_dialog_content = "Mi dama, la base de esos fanáticos de las zanahorias en el oeste de Folta está bajo nuestro control ahora.",
  ui_story_5079_50791100_75_dialog_content = "Aunque requirió mucha persuasión, los que odian las zanahorias en el lado este de la ciudad también han acordado dejar de alborotar.",
  ui_story_5079_50791100_76_dialog_content = "La paz de Folta ha sido restaurada, aunque temporalmente. Sin embargo...",
  ui_story_5079_50791100_77_dialog_content = "El forastero y Popo aún no han sido capturados, ¿verdad?",
  ui_story_5079_50791100_78_dialog_content = "Mi propia insuficiencia es la culpable... Por favor, perdóname...",
  ui_story_5079_50791100_79_dialog_content = "No, esto no tiene nada que ver contigo. Estos eventos han sido predichos desde hace mucho tiempo por el Libro Negro de Cocina...",
  ui_story_5079_50791100_80_dialog_content = "\"Aquellos que lo detestan lo nutrirán. Al hacerlo, también lo terminarán.\"",
  ui_story_5079_50791100_81_dialog_content = "Perdona mi ignorancia, pero ¿qué exactamente significa esta profecía—",
  ui_story_5079_50791100_82_dialog_content = "Significa que los que más desprecian las zanahorias son los responsables de este desastre, y también son los que pondrán fin a él.",
  ui_story_5079_50791100_83_dialog_content = "Son claramente dos personas, pero también son una y la misma... Qué profecía tan interesante.",
  ui_story_5079_50791100_84_dialog_content = "Se han dirigido hacia la cueva del Dios de la Comida, ¿no es así?",
  ui_story_5079_50791100_85_dialog_content = "Sí, mi señora. ¿Deberíamos ir tras ellos?",
  ui_story_5079_50791100_86_dialog_content = "Jejeje, me temo que no. Este sueño no nos pertenece, lo que significa que no tenemos derecho a interferir.",
  ui_story_5079_50791100_87_dialog_content = "Dime, ¿te gustan los cuentos de hadas?",
  ui_story_5079_50791100_88_dialog_content = "¿Cuentos de hadas? Si es tu deseo, siempre puedo leer más de ellos...",
  ui_story_5079_50791100_89_dialog_content = "Un mundo hermoso siempre oculta la cruel y brutal verdad.",
  ui_story_5079_50791100_90_dialog_content = "Pero enfrentar esta crueldad y emerger de ella es caminar hacia la luz.",
  ui_story_5079_50791100_91_dialog_content = "Este ciclo de contradicciones es el camino que conduce a la Verdad.",
  ui_story_5079_50791100_92_dialog_content = "Entiendo.",
  ui_story_5079_50791100_93_dialog_content = "¿Dónde está estacionado el tren ahora mismo?",
  ui_story_5079_50791100_94_dialog_content = "¿El tren? Ya ha ido profundamente al Bosque Crema, y temo que no volverá a Folta pronto.",
  ui_story_5079_50791100_95_dialog_content = "¿Es eso cierto? Si lo hubiera sabido antes, también habría dado un paseo en él.",
  ui_story_5079_50791100_96_dialog_content = "Aunque él no tiene intención de recordar los viejos tiempos conmigo, nunca se sabe cuándo tendremos otra oportunidad como esta...",
  ui_story_5079_50791100_97_dialog_content = "Tu disputa con el conductor se remonta incluso más allá de mi propia vida...",
  ui_story_5079_50791100_98_dialog_content = "No, no tengo derecho a preguntar sobre estas cosas... Por favor, perdóname...",
  ui_story_5079_50791200_1_dialog_content = "<color=#e8d9bb>*pasos*</color>",
  ui_story_5079_50791200_2_dialog_content = "Tus pasos se están volviendo más pesados. ¿Necesitas un descanso?",
  ui_story_5079_50791200_3_dialog_content = "Yo... estoy bien.",
  ui_story_5079_50791200_4_dialog_content = "Si estás bien, entonces no te pellizques la nariz cuando me respondas...",
  ui_story_5079_50791200_5_dialog_content = "De todos modos, realmente pareces conocer bien este lugar. Incluso logramos evitar un par de mafias de Eclipsites. ¿Ya casi llegamos?",
  ui_story_5079_50791200_6_dialog_content = "Por... Por supuesto que conozco bien este lugar... Después de todo, es mi base secreta.",
  ui_story_5079_50791200_7_dialog_content = "Aquí fue donde le ofrecí al Dios de la Comida todas las zanahorias asquerosas que no quería comer...",
  ui_story_5079_50791200_8_dialog_content = "Naturalmente, tuve que... despejar muchos caminos...",
  ui_story_5079_50791200_9_dialog_content = "¿No te preocupaba que el Dios de la Comida te castigara por solo ofrecer las cosas que no querías comer?",
  ui_story_5079_50791200_10_dialog_content = "¡Para nada! Mis ofrendas fueron totalmente sinceras...",
  ui_story_5079_50791200_11_dialog_content = "Recé sinceramente al Dios de la Comida... para eliminar las zanahorias de todas las recetas del mundo!",
  ui_story_5079_50791200_12_dialog_content = "Debes ser bastante sincero ya que gritas así incluso cuando estás tan débil...",
  ui_story_5079_50791200_13_dialog_content = "¿Sabes qué? Creo que hice algo similar cuando era un niño...",
  ui_story_5079_50791200_14_dialog_content = "Desafortunadamente, no me sirvió de mucho. Será mejor que guardes tus fuerzas—",
  ui_story_5079_50791200_15_dialog_content = "Jah... Estamos aquí—la cueva del Dios de la Comida!",
  ui_story_5079_50791200_16_dialog_content = "*tosiendo* Creo... que podría ser... alérgico a las zanahorias...",
  ui_story_5079_50791200_17_dialog_content = "Estoy bastante seguro de que esto no es solo por las zanahorias...",
  ui_story_5079_50791200_18_dialog_content = "Con tantos Eclipsites reunidos aquí, el Darkflow es especialmente denso. Es normal que te sientas afectado por ello.",
  ui_story_5079_50791200_19_dialog_content = "Afortunadamente, la cueva no parece muy profunda. Entraré y echaré un vistazo mientras tú recuperas el aliento en la entrada de la cueva.",
  ui_story_5079_50791200_20_dialog_content = "Piedra de caza, quédate aquí y protege a Popo.",
  ui_story_5079_50791200_21_dialog_content = "...",
  ui_story_5079_50791200_22_dialog_content = "¿Qué pasa? Pensé que ustedes dos eran mejores amigos, ¿entonces por qué te preocupas por mí de nuevo?",
  ui_story_5079_50791200_23_dialog_content = "...",
  ui_story_5079_50791200_24_dialog_content = "Piedra Cazadora... Creo que deberías ir con ella.",
  ui_story_5079_50791200_25_dialog_content = "¡Popo! ¡Ahora no es el momento de actuar valientemente!",
  ui_story_5079_50791200_26_dialog_content = "¡No lo estoy! En mi estado actual, no puedo controlar la Piedra de Caza... Dejarla conmigo sería inútil.",
  ui_story_5079_50791200_27_dialog_content = "No te preocupes, conozco este lugar como la palma de mi mano. ¡Les tomaría a los Eclipsites cien años encontrarme en uno de mis escondites! Jeje...",
  ui_story_5079_50791200_28_dialog_content = "... Entiendo lo que estás diciendo ahora. ¿Quieres que use la Piedra Cazadora para proteger a tu papá si realmente está allí, verdad?",
  ui_story_5079_50791200_29_dialog_content = "No te preocupes, no dejaré que le pase nada.",
  ui_story_5079_50791200_30_dialog_content = "Eso no es lo que quise decir hace un momento... Pero...",
  ui_story_5079_50791200_31_dialog_content = "Por favor... Solo regresa a salvo, tanto tú como mi padre...",
  ui_story_5079_50791200_32_dialog_content = "Ahí está esa sensación de nuevo... ¿Por qué esta cueva se siente tan familiar?",
  ui_story_5079_50791200_33_dialog_content = "Es justo como cuando conocí a la cabeza de la Familia Ketchup y a su asesor. Pero este sentimiento...",
  ui_story_5079_50791200_34_dialog_content = "Es tan triste y doloroso...",
  ui_story_5079_50791200_35_dialog_content = "!",
  ui_story_5079_50791200_36_dialog_content = "Yo... Yo he estado aquí antes, pero la última vez... ¿Fue porque estaba huyendo?",
  ui_story_5079_50791200_37_dialog_content = "...",
  ui_story_5079_50791200_38_dialog_content = "...",
  ui_story_5079_50791200_39_dialog_content = "*sollozando* Si tan solo...",
  ui_story_5079_50791200_40_dialog_content = "Si tan solo hubiera conocido Luminatics antes, entonces tal vez...",
  ui_story_5079_50791200_41_dialog_content = "Quizás mamá no habría sido asesinada por los Eclipsites...",
  ui_story_5079_50791200_42_dialog_content = "Duerme, Pact.",
  ui_story_5079_50791200_43_dialog_content = "Pero... Pero quiero que mamá me abrace de nuevo...",
  ui_story_5079_50791200_44_dialog_content = "¡Basta! Esto no es unas vacaciones; ¡estamos corriendo por nuestras vidas! Los Eclipsites allá afuera—",
  ui_story_5079_50791200_45_dialog_content = "... Por el bien de tu madre, tenemos que hacer todo lo posible para sobrevivir. ¿Entiendes?",
  ui_story_5079_50791200_46_dialog_content = "¡Yo... Yo no quiero entender! ¡Solo quiero a mi madre!",
  ui_story_5079_50791200_47_dialog_content = "...",
  ui_story_5079_50791200_48_dialog_content = "Papá es lo peor... ¿Cómo podría decirme que olvide a mamá?",
  ui_story_5079_50791200_49_dialog_content = "Caminé todo el camino hasta aquí, pero él aún no ha venido a buscarme...",
  ui_story_5079_50791200_50_dialog_content = "Es el peor... ¿Cómo podría decirme que olvide a mamá?",
  ui_story_5079_50791200_51_dialog_content = "¿Eh? Veo luz ahí dentro...",
  ui_story_5079_50791200_52_dialog_content = "<color=#e8d9bb>*pasos*</color>",
  ui_story_5079_50791200_53_dialog_content = "Es este...",
  ui_story_5079_50791200_54_dialog_content = "¿Un ídolo?",
  ui_story_5079_50791200_55_dialog_content = "Si realmente hay un dios allí afuera, entonces devuélveme a mi madre...",
  ui_story_5079_50791200_56_dialog_content = "No, espera... Mamá dijo que necesito ser respetuoso cuando rezo a los dioses. Tengo que ser más maduro en esto...",
  ui_story_5079_50791200_57_dialog_content = "<color=#e8d9bb>Ruido sordo-</color>",
  ui_story_5079_50791200_58_dialog_content = "Deseo que toda esta lucha termine. Deseo tener la fuerza para proteger a mi familia...",
  ui_story_5079_50791200_59_dialog_content = "Por favor, concede mi deseo, y te seguiré y adoraré por el resto de mi vida...",
  ui_story_5079_50791200_X59_dialog_content = "Yo... incluso yo...",
  ui_story_5079_50791200_60_dialog_content = "<color=#e8d9bb>Por mucho tiempo, la pequeña niña se arrodilló ante el ídolo en silenciosa oración.</color>",
  ui_story_5079_50791200_61_dialog_content = "<color=#e8d9bb>En la tranquila oscuridad, su cansado corazón se deslizó lentamente hacia un sueño profundo.</color>",
  ui_story_5079_50791200_62_dialog_content = "<color=#e8d9bb>Estrépito, estrépito—</color>",
  ui_story_5079_50791200_63_dialog_content = "...",
  ui_story_5079_50791200_64_dialog_content = "¿Qué quieres decir?",
  ui_story_5079_50791200_65_dialog_content = "¿Eh? ¿Cu-Cuándo me quedé dormido...?",
  ui_story_5079_50791200_66_dialog_content = "Pact? ¡Así que aquí es donde te has estado escondiendo! ¿Tienes alguna idea de cuánto tiempo he estado buscándote?",
  ui_story_5079_50791200_67_dialog_content = "...",
  ui_story_5079_50791200_68_dialog_content = "!!!",
  ui_story_5079_50791200_69_dialog_content = "¿P-Por qué me miras así...?",
  ui_story_5079_50791200_70_dialog_content = "Pact, necesito que camines lentamente hacia mí sin mirar atrás. ¡Apúrate!",
  ui_story_5079_50791200_71_dialog_content = "¿Sin mirar atrás? ¿Hay algo detrás de mí?",
  ui_story_5079_50791200_72_dialog_content = "...",
  ui_story_5079_50791200_73_dialog_content = "¿Q-Qué...?",
  ui_story_5079_50791200_74_dialog_content = "¿Qué... es esto?",
  ui_story_5079_50791200_75_dialog_content = "Pact, necesito que camines lentamente hacia mí. No tengas miedo y no mires atrás...",
  ui_story_5079_50791200_76_dialog_content = "E-Está bien... Ya voy...",
  ui_story_5079_50791200_77_dialog_content = "¡Graaah!",
  ui_story_5079_50791200_78_dialog_content = "¿¡Qué?! De todos los malos momentos...",
  ui_story_5079_50791200_79_dialog_content = "¡Encuentra un lugar para esconderte, Pact! ¡Yo me encargaré de estos monstruos!!!",
  ui_story_5079_50791200_80_dialog_content = "Papá... No... No tienes ninguna oportunidad contra los Eclipsites...",
  ui_story_5079_50791200_81_dialog_content = "¡Graaah!",
  ui_story_5079_50791200_82_dialog_content = "No... ¡¡¡Nooooo!!!",
  ui_story_5079_50791200_83_dialog_content = "!",
  ui_story_5079_50791200_84_dialog_content = "Graaah...",
  ui_story_5079_50791200_85_dialog_content = "¿Eh? Ese ataque de hace un momento... ¿Lo hice yo?",
  ui_story_5079_50791200_86_dialog_content = "Esta cosa... Esta rueda extraña... ¡Es mi arma!",
  ui_story_5079_50791200_87_dialog_content = "¡Puedo usar Luminatics, papá! ¡Yo... yo puedo protegerte ahora!",
  ui_story_5079_50791200_88_dialog_content = "¡Ya no tenemos que seguir escondiéndonos! ... ¿Padre? ¿Por qué te ves tan molesto?",
  ui_story_5079_50791200_89_dialog_content = "...",
  ui_story_5079_50791200_90_dialog_content = "Veo...",
  ui_story_5079_50791200_91_dialog_content = "¿Así que eras el Dios de la Comida todo el tiempo?",
  ui_story_5079_50791200_92_dialog_content = "Por favor, concede mi deseo, y te seguiré y adoraré por el resto de mi vida...",
  ui_story_5079_50791200_93_dialog_content = "Supongo que nunca seré libre de tus cadenas, ¿eh?",
  ui_story_5079_50791200_94_dialog_content = "...",
  ui_story_5079_50791200_95_dialog_content = "¿Piedra de Caza?",
  ui_story_5079_50791200_96_dialog_content = "...",
  ui_story_5079_50791200_97_dialog_content = "Oye, ¿qué estás haciendo? No te dije que fueras allí...",
  ui_story_5079_50791200_98_dialog_content = "!",
  ui_story_5079_50791200_99_dialog_content = "¿Se están fusionando?",
  ui_story_5079_50791200_100_dialog_content = "No... Solo está volviendo a su forma original.",
  ui_story_5079_50791200_101_dialog_content = "Esta es la casa de la Piedra de Caza. El lugar al que pertenece...",
  ui_story_5079_50791200_102_dialog_content = "No me estaba siguiendo desde el principio. Todo este tiempo, lo estaba alejando de su hogar...",
  ui_story_5079_50791200_103_dialog_content = "!",
  ui_story_5079_50791200_104_dialog_content = "¿Podrías calmarte? Solo estás en casa, eso es todo... No necesitas emocionarte tanto.",
  ui_story_5079_50791200_105_dialog_content = "O tal vez soy yo... Tal vez simplemente soy incapaz de tener ese sentimiento.",
  ui_story_5079_50791200_106_dialog_content = "Después de todo, ya no tengo un hogar al que volver...",
  ui_story_5079_50791200_107_dialog_content = "Nunca quise que estuvieras cerca de todos modos. De esta manera, todos obtienen lo que quieren.",
  ui_story_5079_50791200_108_dialog_content = "Voy a buscar al padre de Popo ahora, así que...",
  ui_story_5079_50791200_109_dialog_content = "!",
  ui_story_5079_50791200_110_dialog_content = "Ven si quieres, pero si decides quedarte aquí...",
  ui_story_5079_50791200_111_dialog_content = "Entonces esto es adiós.",
  ui_story_5079_50791200_112_dialog_content = "También será para siempre... ¿Me escuchas?",
  ui_story_5079_50791200_113_dialog_content = "!",
  ui_story_5079_50791200_114_dialog_content = "Deja de fingir ya... Haces que parezca una decisión tan difícil, pero no te estás moviendo en absoluto, ¿verdad?",
  ui_story_5079_50791200_115_dialog_content = "¡Realmente me voy! ¿Ves? Me estoy alejando...",
  ui_story_5079_50791200_116_dialog_content = "!",
  ui_story_5079_50791200_117_dialog_content = "Bien. Veo que ya has tomado tu decisión.",
  ui_story_5079_50791200_118_dialog_content = "Adiós, Piedra de Caza.",
  ui_story_5079_50791301_1_dialog_content = "<color=#e8d9bb>*pasos*</color>",
  ui_story_5079_50791301_2_dialog_content = "Ese idiota, realmente se quedó atrás... Debe ser agradable tener un lugar al que llamar hogar.",
  ui_story_5079_50791301_3_dialog_content = "¿Podría cumplirse mi deseo tan fácilmente? Parece demasiado bueno para ser verdad, y eso me molesta.",
  ui_story_5079_50791301_4_dialog_content = "¿Qué es exactamente esa cosa? Todavía no tengo idea...",
  ui_story_5079_50791301_5_dialog_content = "¡Ah, pero eso ya no importa! Lo único que importa es que conseguí mi deseo, ¿verdad?",
  ui_story_5079_50791301_6_dialog_content = "...",
  ui_story_5079_50791301_7_dialog_content = "¡Ahí tienes!",
  ui_story_5079_50791301_8_dialog_content = "¡Ey! ¿Estás bien?",
  ui_story_5079_50791301_9_dialog_content = "Urgh...",
  ui_story_5079_50791301_10_dialog_content = "Bien, tus heridas no parecen demasiado graves. Vamos, ¡levántate!",
  ui_story_5079_50791301_11_dialog_content = "¡Oye, oye! Ahora no es el momento para una siesta... ¡Tu hija te está esperando afuera!",
  ui_story_5079_50791301_12_dialog_content = "M-Mi hija...",
  ui_story_5079_50791301_13_dialog_content = "¡Eso es correcto! Saliste aquí para encontrar a Popo, ¿no es así?",
  ui_story_5079_50791301_14_dialog_content = "P-Popo?",
  ui_story_5079_50791301_15_dialog_content = "¿Popo, eres realmente tú? Oh, gracias a Dios... ¡Estoy tan contento de que estés a salvo!",
  ui_story_5079_50791301_16_dialog_content = "Me equivoqué, Popo... Fui demasiado duro contigo antes. ¿Cómo podría no quererte?",
  ui_story_5079_50791301_17_dialog_content = "¿Demasiado difícil? Urgh... Mi cabeza...",
  ui_story_5079_50791301_18_dialog_content = "¡Mira, Popo! ¡Esta es la mejor zanahoria que he producido en mi vida! Uno de nuestros clientes habituales insistió en que se la vendiera, pero lo rechacé...",
  ui_story_5079_50791301_19_dialog_content = "*suspiros* Popo todavía se niega a comer sus zanahorias. Qué niña más terca.",
  ui_story_5079_50791301_20_dialog_content = "Supongo que tendré que comprarle algunos dulces esta vez... Pero no seré tan generoso la próxima vez que rechace su comida...",
  ui_story_5079_50791301_21_dialog_content = "Popo finalmente aprendió a usar Luminatics, pero... solo desearía que pudiera ser un poco más educada.",
  ui_story_5079_50791301_22_dialog_content = "No puedo enseñarle nada... Soy un padre tan inútil...",
  ui_story_5079_50791301_23_dialog_content = "Si solo hubiera un noble Aurorian que pudiera enseñarle, pero no conozco a nadie así en absoluto...",
  ui_story_5079_50791301_24_dialog_content = "¡Tu vestido está lleno de agujeros otra vez! ¿Por qué no puedes simplemente deshacerte de esta cosa tan fea?",
  ui_story_5079_50791301_25_dialog_content = "¡Yo... yo solo quiero tener una vida normal con mi hija normal! ¿Es mucho pedir?",
  ui_story_5079_50791301_26_dialog_content = "¡Piensa! Tiene que haber alguna manera de hacer que esto desaparezca! ¡Yo... Yo...",
  ui_story_5079_50791301_27_dialog_content = "Olvídalo... Nunca tendré una tienda de alta gama mientras viva...",
  ui_story_5079_50791301_28_dialog_content = "Pero como mínimo, tenemos que vivir bien... Encontraré un arreglo que funcione solo para ti.",
  ui_story_5079_50791301_29_dialog_content = "¿Cómo suena eso, Popo?",
  ui_story_5079_50791301_30_dialog_content = "¿Quieres que acepte tu arreglo? ¡Ni pensarlo! Especialmente después de que dijiste que no tenía esperanza en tu carta...",
  ui_story_5079_50791301_31_dialog_content = "!",
  ui_story_5079_50791301_32_dialog_content = "Espera... ¿Qué acabo de ver? Tú eres... el padre de Popo...",
  ui_story_5079_50791301_33_dialog_content = "Lo siento, pero no soy tu hija. Tendrás que guardar esas palabras para ella, no para mí.",
  ui_story_5079_50791301_34_dialog_content = "Soy... solo soy el detective que está ayudando a Popo a encontrarte. Dime, ¿tienes alguna idea de lo que está pasando en Folta, o qué lo está causando?",
  ui_story_5079_50791301_35_dialog_content = "¿Eh? ¿Está pasando algo en Folta?",
  ui_story_5079_50791301_36_dialog_content = "No tengo idea de lo que estás hablando. ¿Qué está pasando en nuestro pueblo? Espera...",
  ui_story_5079_50791301_37_dialog_content = "¿No eres tú... la mujer joven que vi en el tren esta mañana?",
  ui_story_5079_50791301_38_dialog_content = "¡Por favor, perdóname por confundirte con mi hija! No quise ofenderte, ¡señorita!",
  ui_story_5079_50791301_39_dialog_content = "¿Dijiste que la has estado ayudando? ¿Una dama noble y refinada como tú?",
  ui_story_5079_50791301_40_dialog_content = "¡Sabía por tu apariencia digna que eras una persona noble y de alta clase!",
  ui_story_5079_50791301_41_dialog_content = "¡Supongo que mi padre mentía cuando decía que las personas bien vestidas se comportan mejor que las demás!",
  ui_story_5079_50791301_42_dialog_content = "Parece que Popo recuerda claramente las palabras de su padre...",
  ui_story_5079_50791301_43_dialog_content = "Pero apenas creo que el carácter de alguien tenga algo que ver con su ropa.",
  ui_story_5079_50791301_44_dialog_content = "Hay muchas personas de aspecto digno que hacen cosas vergonzosas en secreto, al igual que hay personas que ayudan a los menos privilegiados a pesar de vestir harapos ellos mismos.",
  ui_story_5079_50791301_45_dialog_content = "Sí... Creo que tienes razón.",
  ui_story_5079_50791301_46_dialog_content = "Y en ese sentido, ser excesivamente halagador no es ser cortés. Si acaso, solo hace que la gente te desagrade aún más...",
  ui_story_5079_50791301_47_dialog_content = "Yo... Lo siento mucho...",
  ui_story_5079_50791301_48_dialog_content = "Urgh... Olvídalo. No debería estar enseñándote modales ahora mismo...",
  ui_story_5079_50791301_49_dialog_content = "Incluso si no sabes lo que está pasando en el pueblo, debes tener alguna idea de qué está detrás del olor a zanahorias en esta cueva, ¿verdad?",
  ui_story_5079_50791301_50_dialog_content = "Si no resolvemos esto, tu tienda de zanahorias será cerrada para siempre.",
  ui_story_5079_50791301_51_dialog_content = "El olor de las zanahorias... ¡Ah! ¿Podría tener algo que ver con la cosa que me atacó?",
  ui_story_5079_50791301_52_dialog_content = "¿Qué \"cosa\"?",
  ui_story_5079_50791301_53_dialog_content = "Puede que no me creas... pero creo que fui noqueado por un monstruoso gigante de zanahoria.",
  ui_story_5079_50791301_54_dialog_content = "¿Un monstruo de zanahoria? ¿Podría ser algún tipo de Eclipsite aún por descubrir?",
  ui_story_5079_50791301_55_dialog_content = "N-No estoy seguro, pero... todo esto puede ser mi culpa...",
  ui_story_5079_50791301_56_dialog_content = "Después de todo, mi hija Popo se escapó de casa por mi culpa, y no pude encontrarla en ningún lugar...",
  ui_story_5079_50791301_57_dialog_content = "Así que comencé a buscar respuestas en las supersticiones populares, y gasté una gran suma de dinero en un llamado \"tributo supremo\".",
  ui_story_5079_50791301_58_dialog_content = "Quería ofrecérselo al Dios de la Comida e implorar a la deidad que encontrara a mi hija.",
  ui_story_5079_50791301_59_dialog_content = "\"¿Una gran suma de dinero\"? No tenía idea de que te importara tanto Popo...",
  ui_story_5079_50791301_60_dialog_content = "¡Por supuesto que sí! Ella es mi hija, así como la única familia que me queda en este mundo.",
  ui_story_5079_50791301_61_dialog_content = "La única familia que te queda... Parece que realmente lo dices en serio, entonces, ¿cómo terminaron las cosas así?",
  ui_story_5079_50791301_62_dialog_content = "¡Yo... Yo no tenía idea de que el supremo tributo sería absorbido por una zanahoria disfrazada de ídolo!",
  ui_story_5079_50791301_63_dialog_content = "En ese momento, se transformó en un monstruo enorme y juró destruir a todos los que odian las zanahorias.",
  ui_story_5079_50791301_64_dialog_content = "No puedo recordar lo que pasó después de eso...",
  ui_story_5079_50791301_65_dialog_content = "¿Puedes describirme este \"tributo supremo\"?",
  ui_story_5079_50791301_66_dialog_content = "Era... un objeto brillante en forma de diamante...",
  ui_story_5079_50791301_67_dialog_content = "Espera un segundo... ¡Eso suena justo como una Semilla! ¡La cosa que puede convertir a los Aurorians en Eclipsites!",
  ui_story_5079_50791301_68_dialog_content = "¡Eso explicaría por qué este olor a zanahoria atrajo a todos esos Eclipsites afuera!",
  ui_story_5079_50791301_69_dialog_content = "Si realmente amas a tu hija, deberías esforzarte más por llevarte bien con ella, ¡y no recurrir a estos métodos locos cuando las cosas salen mal!",
  ui_story_5079_50791301_70_dialog_content = "¿Qué harás si las consecuencias son irreversibles? ¡Porque esa puede ser una posibilidad ahora!",
  ui_story_5079_50791301_71_dialog_content = "Popo es una niña tan buena... Aunque peleen todo el tiempo, ella siempre está pensando en ti...",
  ui_story_5079_50791301_72_dialog_content = "Yo... Yo sé que ella es una buena niña. Lo sé mejor que nadie.",
  ui_story_5079_50791301_73_dialog_content = "Pero las actitudes de un niño deben formarse temprano, y no puedes elogiarlos por todo lo que hacen. Solo—",
  ui_story_5079_50791301_74_dialog_content = "¿Solo qué? ¡Eso no es más que un pensamiento ilusorio y unilateral!",
  ui_story_5079_50791301_75_dialog_content = "¿Alguna vez has escuchado realmente sus sentimientos sobre esto?",
  ui_story_5079_50791301_76_dialog_content = "Te gustan las zanahorias, así que piensas que a tu niño también tienen que gustarle.",
  ui_story_5079_50791301_77_dialog_content = "Quieres que ella aprenda Luminatics, así que no tiene más opción que aprenderlos.",
  ui_story_5079_50791301_78_dialog_content = "¡Y ahora que puede usar Luminatics, apuesto a que deseas que sus Luminatics sean tan poderosos y elegantes como los de un noble de Lumopolis! Este \"amor\" tuyo—",
  ui_story_5079_50791301_79_dialog_content = "¿No crees que es demasiado para ella soportar?",
  ui_story_5079_50791301_80_dialog_content = "Yo... Espera, ¿Popo puede usar Luminatics ahora?",
  ui_story_5079_50791301_81_dialog_content = "...",
  ui_story_5079_50791301_82_dialog_content = "... Olvida que dije algo. No estoy tratando de cambiar nada aquí, pero solo espero que intentes ser más digno del amor de Popo.",
  ui_story_5079_50791301_83_dialog_content = "Sí, ella aprendió a usar Luminatics... y todo es gracias a los Eclipsites que trajiste aquí.",
  ui_story_5079_50791301_84_dialog_content = "Aún así... Las Semillas suelen ser absorbidas solo por los Aurorianos. ¿Cómo logró una zanahoria usarla para convertirse en un Eclipsite?",
  ui_story_5079_50791301_85_dialog_content = "Además, no recuerdo haber visto ningún monstruo de zanahoria en el camino hasta aquí... Espera un minuto...",
  ui_story_5079_50791301_86_dialog_content = "...",
  ui_story_5079_50791301_87_dialog_content = "¿No son estos los fragmentos de ese ídolo que vi antes? ¿Por qué aquí?",
  ui_story_5079_50791301_88_dialog_content = "¡Oh, no! No me digas que ese ídolo es...",
  ui_story_5079_50791301_89_dialog_content = "¡Yo... Yo creo que puedo oler la fuente del sabor a zanahoria! ¡Como si estuviera conectado a mí de alguna manera!",
  ui_story_5079_50791301_90_dialog_content = "¡El olor a zanahorias viene de la cueva del Dios de la Comida! ¡Ahora estoy seguro de ello!",
  ui_story_5079_50791301_91_dialog_content = "También escucho una voz... ¡Me está diciendo que me acerque!",
  ui_story_5079_50791301_92_dialog_content = "¡Popo está en problemas!",
  ui_story_5079_50791301_93_dialog_content = "¿Qué es eso?",
  ui_story_5079_50791301_94_dialog_content = "¡Está esperando justo fuera de la cueva! ¡Tenemos que volver con ella!",
  ui_story_5079_50791301_95_dialog_content = "¡Graaah!",
  ui_story_5079_50791301_96_dialog_content = "No tengo tiempo para perder contigo, ¡ahora sal de mi camino!",
  ui_story_5079_50791401_1_dialog_content = "<color=#828282>¡Whoosh!</color>",
  ui_story_5079_50791401_2_dialog_content = "Graah...",
  ui_story_5079_50791401_3_dialog_content = "Ese fue el último. Deberíamos—",
  ui_story_5079_50791401_4_dialog_content = "...",
  ui_story_5079_50791401_5_dialog_content = "¡Oye! ¡No sabemos qué nos espera allá afuera! No puedes usar Luminatics, ¡así que ponte detrás de mí!",
  ui_story_5079_50791401_6_dialog_content = "¡Popo! Popo, ¿dónde estás?",
  ui_story_5079_50791401_7_dialog_content = "Tsk, él es tan malo escuchando como Popo. Supongo que realmente se parecen...",
  ui_story_5079_50791401_8_dialog_content = "<size=45>Popo—</size>",
  ui_story_5079_50791401_9_dialog_content = "¿Eh? ¿Acabo de escuchar la voz de papá?",
  ui_story_5079_50791401_10_dialog_content = "<size=45>¡Padre! ¡Estoy aquí!</size>",
  ui_story_5079_50791401_11_dialog_content = "¡Quédate justo ahí, Popo! ¡Voy a buscarte!",
  ui_story_5079_50791401_12_dialog_content = "¡Para! Escucho algo moviéndose...",
  ui_story_5079_50791401_13_dialog_content = "Clac... Clac, clac, clac—",
  ui_story_5079_50791401_14_dialog_content = "¡Boom!",
  ui_story_5079_50791401_15_dialog_content = "Correos...",
  ui_story_5079_50791401_16_dialog_content = "¡Popopo!",
  ui_story_5079_50791401_17_dialog_content = "¡Lo sabía! El monstruo de zanahoria se disfrazó como el ídolo afuera!",
  ui_story_5079_50791401_18_dialog_content = "Escoria desvergonzada... ¡Ha estado haciéndose pasar por el Dios de la Comida y tomando las ofrendas de la gente para sí mismo!",
  ui_story_5079_50791401_19_dialog_content = "¡Po... Popo!",
  ui_story_5079_50791401_20_dialog_content = "Espera, ¿a dónde va? ¡Oye! ¡Tu oponente está aquí!",
  ui_story_5079_50791401_21_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5079_50791401_22_dialog_content = "¡Ignora completamente mis ataques! ¡Oye! ¡Alto ahí!",
  ui_story_5079_50791401_23_dialog_content = "¡Popopo!",
  ui_story_5079_50791401_24_dialog_content = "¡S-Quédate atrás... No te acerques más!",
  ui_story_5079_50791401_25_dialog_content = "¡T-Toma esto!",
  ui_story_5079_50791401_26_dialog_content = "<color=#e8d9bb>Golpe—</color>",
  ui_story_5079_50791401_27_dialog_content = "¿Po? Popopo...",
  ui_story_5079_50791401_28_dialog_content = "La Luminática de Popo... No puedo creer que finalmente estoy viendo los poderes de mi hija por mí mismo...",
  ui_story_5079_50791401_29_dialog_content = "¿Realmente es este el momento para quedarse asombrado? ¡Ve a encontrar un lugar seguro para esconderte!",
  ui_story_5079_50791401_30_dialog_content = "Pero mi hija...",
  ui_story_5079_50791401_31_dialog_content = "¡Déjala a mí!",
  ui_story_5079_50791401_32_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5079_50791401_33_dialog_content = "Popopo... ¡Tus ataques son inútiles contra mí! No tengo ningún interés en ti...",
  ui_story_5079_50791401_34_dialog_content = "...",
  ui_story_5079_50791401_35_dialog_content = "Pero tú, Popo... Incluso con un nombre tan maravilloso, ¡todavía desprecias las zanahorias!",
  ui_story_5079_50791401_36_dialog_content = "¡Tu odio hacia ellos alimenta mi poder!",
  ui_story_5079_50791401_37_dialog_content = "Tenía razón. ¡Esta cosa realmente va tras Popo!",
  ui_story_5079_50791401_38_dialog_content = "¡Piedra de Caza! No espera, no es—",
  ui_story_5079_50791401_39_dialog_content = "¡Popopo! ¿Te refieres a esto, por casualidad?",
  ui_story_5079_50791401_40_dialog_content = "!",
  ui_story_5079_50791401_41_dialog_content = "¡Piedra de Caza... Devuélvemela!",
  ui_story_5079_50791401_42_dialog_content = "¡Rueda inútil! ¿Vas a dejar que este monstruo te use así? Ven aquí ahora mismo...",
  ui_story_5079_50791401_43_dialog_content = "Urgh...",
  ui_story_5079_50791401_44_dialog_content = "¡Popopo!",
  ui_story_5079_50791401_45_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5079_50791401_46_dialog_content = "La Piedra de Caza... ¿Ya no me escucha?",
  ui_story_5079_50791401_47_dialog_content = "Estoy muy agradecido por el arma que me diste.",
  ui_story_5079_50791401_48_dialog_content = "Pero sobre todo, estoy agradecido contigo, Popo...",
  ui_story_5079_50791401_49_dialog_content = "Todo lo que necesito es un bocado más, un último bocado delicioso de odio, ¡y puedo gobernar cada pedazo de comida en este mundo!",
  ui_story_5079_50791401_50_dialog_content = "¡Pronto bendeciré no solo a Folta, sino a todo Astra con el sabor crujiente e irresistible de las zanahorias!",
  ui_story_5079_50791401_51_dialog_content = "¡Popopo!",
  ui_story_5079_50791401_52_dialog_content = "No... ¡Tú no puedes! El mundo no puede terminar así...",
  ui_story_5079_50791401_53_dialog_content = "\"¿No puedes\", dices? Popopo... ¡No estoy de acuerdo! Después de todo, nunca me habría vuelto tan poderoso si no me hubieras abandonado aquí!",
  ui_story_5079_50791401_54_dialog_content = "Correos... Correos...",
  ui_story_5079_50791401_55_dialog_content = "¿Cómo... Cómo podrías dejar una zanahorita tan linda aquí completamente sola?",
  ui_story_5079_50791401_56_dialog_content = "Está oscuro... Muy oscuro... No hay nutrientes... No tengo fuerzas...",
  ui_story_5079_50791401_57_dialog_content = "¡Todopoderoso Dios de la Comida, deseo vivir en un mundo sin zanahorias!",
  ui_story_5079_50791401_58_dialog_content = "¿Por qué alguno de nosotros tiene que comer algo tan asqueroso que ni siquiera debería existir?",
  ui_story_5079_50791401_59_dialog_content = "¡Te lo suplico! ¡Por favor, elimina las zanahorias de todas las recetas conocidas en el mundo!",
  ui_story_5079_50791401_60_dialog_content = "Yo... nunca debería haber... aparecido en este mundo...",
  ui_story_5079_50791401_61_dialog_content = "Odiado, abandonado, innecesario...",
  ui_story_5079_50791401_62_dialog_content = "Oh poderoso Dios de la Comida, por favor bendice a nuestra familia con paz y seguridad...",
  ui_story_5079_50791401_63_dialog_content = "¡Escucha mi súplica, amable Dios de la Comida! ¡Por favor, haz que esa chica se enamore de mí!",
  ui_story_5079_50791401_64_dialog_content = "Por favor acepta mis ofrendas, Dios de la Comida...",
  ui_story_5079_50791401_65_dialog_content = "Dios de la Comida, Dios de la Comida... Es solo una estatua, ¿no es así? ¿Por qué todos siguen pidiéndole que conceda sus deseos?",
  ui_story_5079_50791401_66_dialog_content = "Rezan y suplican, pero nunca pasa nada... No merece su adoración...",
  ui_story_5079_50791401_67_dialog_content = "¡Pero yo sí... Porque soy real! ¡Estoy vivo!",
  ui_story_5079_50791401_68_dialog_content = "¡Notame! ¡Mírame! ¡Adórame! Soy mejor que esa estatua... porque puedo hacer tus sueños realidad!",
  ui_story_5079_50791401_69_dialog_content = "...",
  ui_story_5079_50791401_70_dialog_content = "¡Popopo!",
  ui_story_5079_50791401_71_dialog_content = "Además, el Dios de la Comida nunca responderá a tus oraciones. En su lugar—",
  ui_story_5079_50791401_72_dialog_content = "¡Disfrutaré de tus generosas ofrendas!",
  ui_story_5079_50791401_73_dialog_content = "Oh Dios de la Comida, por favor acepta esta zanahoria como mi ofrenda. Con un solo sabor sabrás exactamente por qué las odio tanto.",
  ui_story_5079_50791401_74_dialog_content = "Sí, Popo... ¡Sigue odiándolos! ¡Sigue odiándome! ¡Solo me hace más fuerte!",
  ui_story_5079_50791401_75_dialog_content = "Oh Dios de la Comida, ¿puedes hacer que mi irritante esposo desaparezca?",
  ui_story_5079_50791401_76_dialog_content = "¡Sí, sí! Con gusto concederé un deseo tan deliciosamente odioso!",
  ui_story_5079_50791401_77_dialog_content = "... Por favor acepte este supremo tributo a cambio de encontrar a mi hija...",
  ui_story_5079_50791401_78_dialog_content = "Sí... ¡Sí! ¿Tienes alguna idea de cuánto tiempo he esperado este momento?",
  ui_story_5079_50791401_79_dialog_content = "... ¿Mmm?",
  ui_story_5079_50791401_80_dialog_content = "Po... ¡Popopo!",
  ui_story_5079_50791401_81_dialog_content = "...",
  ui_story_5079_50791401_82_dialog_content = "¿Así que todo esto sucedió por mi culpa?",
  ui_story_5079_50791401_83_dialog_content = "Este monstruo de zanahoria... era la zanahoria que dejé aquí hace mucho tiempo.",
  ui_story_5079_50791401_84_dialog_content = "¡En efecto, y ahora ha llegado el momento de pagarte en su totalidad!",
  ui_story_5079_50791401_85_dialog_content = "¡Ahhh—!",
  ui_story_5079_50791401_86_dialog_content = "¡Popo!",
  ui_story_5079_50791401_87_dialog_content = "¡El monstruo de la zanahoria está utilizando el poder de Hunting Stone para hacer crecer espinas en sus zarcillos!",
  ui_story_5079_50791401_88_dialog_content = "Tsk... Si la Piedra de Caza no se hubiera convertido en su arma, esa estúpida zanahoria no habría sido tan poderosa!",
  ui_story_5079_50791401_89_dialog_content = "¡Ahora no es el momento para que me compliques aún más las cosas, idiota!",
  ui_story_5079_50791401_90_dialog_content = "¡Suéltala... Suéltala a mi hija!",
  ui_story_5079_50791401_91_dialog_content = "¿Ah?",
  ui_story_5079_50791401_92_dialog_content = "Espera, ¿qué crees que estás haciendo? Ni siquiera puedes usar Luminatics...",
  ui_story_5079_50791401_93_dialog_content = "Si no puedo usar Luminatics, usaré palos y piedras para pelear.",
  ui_story_5079_50791401_94_dialog_content = "¡Incluso sin esos, todavía tengo mis puños!",
  ui_story_5079_50791401_95_dialog_content = "¡Solo estás pidiendo que te maten!",
  ui_story_5079_50791401_96_dialog_content = "*tose* Ese monstruo tiene a mi pequeña niña. Aunque me cueste la vida, ¡tengo que salvarla!",
  ui_story_5079_50791401_97_dialog_content = "¡Suéltala!",
  ui_story_5079_50791401_98_dialog_content = "Te dije que me la dejaras a mí... Urgh...",
  ui_story_5079_50791401_99_dialog_content = "Mi cabeza... ¿Por qué tiene que suceder esto ahora...",
  ui_story_5079_50791401_100_dialog_content = "¿Quién eres? ¡Aléjate de mi hija!",
  ui_story_5079_50791401_101_dialog_content = "¡Suéltala ahora mismo, o te arrepentirás!",
  ui_story_5079_50791401_102_dialog_content = "¡Aléjate de ella ahora mismo, o te arrepentirás!",
  ui_story_5079_50791401_103_dialog_content = "Detente, déjame...",
  ui_story_5079_50791401_104_dialog_content = "¡Popopo!",
  ui_story_5079_50791401_105_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5079_50791401_106_dialog_content = "Urgh... ¿Eso es todo lo que tienes? Ven a por mí, monstruo!",
  ui_story_5079_50791401_107_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5079_50791401_108_dialog_content = "¡No he terminado aún... Suéltala!",
  ui_story_5079_50791401_109_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5079_50791401_110_dialog_content = "Esto... Esto aún no ha terminado...",
  ui_story_5079_50791401_111_dialog_content = "Date prisa, Popo... Te quitaré las espinas...",
  ui_story_5079_50791401_112_dialog_content = "<color=#e8d9bb>Puñalada—</color>",
  ui_story_5079_50791401_113_dialog_content = "Padre... ¡Tus manos están sangrando demasiado! A este ritmo, tú—",
  ui_story_5079_50791401_114_dialog_content = "¡No te preocupes por mí! ¡Solo vete, papá! Esto es... todo mi culpa de todos modos...",
  ui_story_5079_50791401_115_dialog_content = "Eso es por lo que debería—",
  ui_story_5079_50791401_116_dialog_content = "¡Eso es suficiente! Yo soy el que compró ese maldito tributo... Si tan solo fuera más comprensivo...",
  ui_story_5079_50791401_117_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5079_50791401_118_dialog_content = "Urgh... ¿Finalmente lo está dejando ir? A-Apúrate, Popo...",
  ui_story_5079_50791401_119_dialog_content = "Padre...",
  ui_story_5079_50791401_120_dialog_content = "Necesito que te des la vuelta y camines hacia la entrada de la cueva... No tengas miedo, y no mires atrás...",
  ui_story_5079_50791401_121_dialog_content = "Pact, necesito que camines lentamente hacia mí. No tengas miedo y no mires atrás...",
  ui_story_5079_50791401_122_dialog_content = "D-Date prisa...",
  ui_story_5079_50791401_123_dialog_content = "P-padre?",
  ui_story_5079_50791401_124_dialog_content = "Esta vez, no estoy rezando a nadie ni a nada más...",
  ui_story_5079_50791401_125_dialog_content = "¡Salvaré a mi familia con mis propias dos manos!",
  ui_story_5079_50791501_1_dialog_content = "<color=#828282>¡Whoosh!</color>",
  ui_story_5079_50791501_2_dialog_content = "Correos...",
  ui_story_5079_50791501_3_dialog_content = "*jadeando* Finalmente...",
  ui_story_5079_50791501_4_dialog_content = "¿Todavía puedes moverte, Popo? Necesitas... apurarte...",
  ui_story_5079_50791501_5_dialog_content = "El monstruo de la zanahoria está tras de ti. Si logra absorber tu odio, no tendremos ninguna oportunidad contra él...",
  ui_story_5079_50791501_6_dialog_content = "Pero... Pero mi padre, él...",
  ui_story_5079_50791501_7_dialog_content = "Te traeré a tu padre después de que derrote a esa cosa.",
  ui_story_5079_50791501_8_dialog_content = "¡Pero ahora mismo necesitas salir de aquí, ¿entiendes? ¡Este será tu mayor desafío hasta ahora!",
  ui_story_5079_50791501_9_dialog_content = "Yo... ¡yo puedo hacerlo!",
  ui_story_5079_50791501_10_dialog_content = "¡No! ¡No puedes escaparte de mí!",
  ui_story_5079_50791501_11_dialog_content = "¡Tu oponente está aquí!",
  ui_story_5079_50791501_12_dialog_content = "<color=#828282>¡Whoosh!</color>",
  ui_story_5079_50791501_13_dialog_content = "Correos...",
  ui_story_5079_50791501_14_dialog_content = "Tsk, ¿todavía no hay daño, huh? Se siente como...",
  ui_story_5079_50791501_15_dialog_content = "Popopo... Como si te faltara algo, ¿verdad?",
  ui_story_5079_50791501_16_dialog_content = "Si no me equivoco, has usado casi todo tu poder, ¿no es así?",
  ui_story_5079_50791501_17_dialog_content = "¿Qué podrías hacer posiblemente sin esta arma?",
  ui_story_5079_50791501_18_dialog_content = "Tsk... ¡No me subestimes, monstruo!",
  ui_story_5079_50791501_19_dialog_content = "<color=#e8d9bb>¡Swoosh! Golpe—</color>",
  ui_story_5079_50791501_20_dialog_content = "...",
  ui_story_5079_50791501_21_dialog_content = "¿Ya estás en tu límite? ¡Qué decepcionante!",
  ui_story_5079_50791501_22_dialog_content = "Con esta arma que me diste... ¡Apenas estoy comenzando!",
  ui_story_5079_50791501_23_dialog_content = "¡Urgh!",
  ui_story_5079_50791501_24_dialog_content = "Así que este es el poder de Hunting Stone... Je, esta es mi primera vez... experimentándolo por mí mismo...",
  ui_story_5079_50791501_25_dialog_content = "Supongo que también debería demostrarte mi poder...",
  ui_story_5079_50791501_26_dialog_content = "<color=#e8d9bb>¡Swoosh! Golpe—</color>",
  ui_story_5079_50791501_27_dialog_content = "*tose* No me estás dando ninguna holgura hoy, ¿verdad?",
  ui_story_5079_50791501_28_dialog_content = "¿Es este el resentimiento que sientes hacia mí, Hunting Stone? Jeje...",
  ui_story_5079_50791501_29_dialog_content = "Lo merezco, supongo.",
  ui_story_5079_50791501_30_dialog_content = "Pensé que te negaste a venir conmigo, pero todo este tiempo estuviste bajo el control de este monstruo de zanahoria...",
  ui_story_5079_50791501_31_dialog_content = "Me has estado ayudando todo este tiempo, pero di por sentada tu bondad y constantemente me quejé de querer deshacerme de ti...",
  ui_story_5079_50791501_32_dialog_content = "Seguí diciéndome a mí mismo que esto era lo que quería... Me atrapé en una mentira obstinada.",
  ui_story_5079_50791501_33_dialog_content = "Y por eso... te entregué al enemigo.",
  ui_story_5079_50791501_34_dialog_content = "<color=#e8d9bb>¡Swoosh! Golpe—</color>",
  ui_story_5079_50791501_35_dialog_content = "Tsk, ya no sé qué hacer...",
  ui_story_5079_50791501_36_dialog_content = "¡Popopo! ¡Siente el aguijón aplastante de mis tentáculos potenciados!",
  ui_story_5079_50791501_37_dialog_content = "¡Aaahhhh!",
  ui_story_5079_50791501_38_dialog_content = "...",
  ui_story_5079_50791501_39_dialog_content = "Urgh... Estoy bien. Después de todo, esta no es la primera vez... que Hunting Stone me ha atado.",
  ui_story_5079_50791501_40_dialog_content = "Es bueno que Popo no esté aquí para ver esto, o sino me lanzaría aún más insultos...",
  ui_story_5079_50791501_41_dialog_content = "Él tampoco está aquí para salvarme esta vez...",
  ui_story_5079_50791501_42_dialog_content = "El único que puede ayudarme ahora mismo...",
  ui_story_5079_50791501_43_dialog_content = "...",
  ui_story_5079_50791501_44_dialog_content = "Todo esto se siente tan familiar...",
  ui_story_5079_50791501_45_dialog_content = "... ¡Urgh!",
  ui_story_5079_50791501_46_dialog_content = "Sí, lucha y sufre... ¡Solo hará que tus ataduras sean aún más apretadas!",
  ui_story_5079_50791501_47_dialog_content = "Yo... No necesito que me digas eso... Pero...",
  ui_story_5079_50791501_48_dialog_content = "N-No quiero perder... Piedra de Caza.",
  ui_story_5079_50791501_49_dialog_content = "No quiero perder... el derecho de tenerte a mi lado...",
  ui_story_5079_50791501_50_dialog_content = "...",
  ui_story_5079_50791501_51_dialog_content = "¿No extrañas rodar sobre mi cara cuando estoy durmiendo?",
  ui_story_5079_50791501_52_dialog_content = "¿O asustando a la gente en el peor momento posible?",
  ui_story_5079_50791501_53_dialog_content = "¿No extrañas perforar accidentalmente mi vestido, o incluso hacerlo a propósito?",
  ui_story_5079_50791501_55_dialog_content = "...",
  ui_story_5079_50791501_56_dialog_content = "Yo... pertenezco... a Pact...",
  ui_story_5079_50791501_57_dialog_content = "Pero... por favor... recuerda...",
  ui_story_5079_50791501_58_dialog_content = "Mi fuerza... todo viene...",
  ui_story_5079_50791501_59_dialog_content = "¡De... tú!",
  ui_story_5079_50791501_60_dialog_content = "Piedra de Caza... ¿Realmente puedes hablar?",
  ui_story_5079_50791501_61_dialog_content = "¿Qué son estas imágenes que estoy viendo?",
  ui_story_5079_50791501_62_dialog_content = "¿Son estos... mis primeros recuerdos con la Piedra de Caza?",
  ui_story_5079_50791501_63_dialog_content = "Ay... Este poder... Realmente duele.",
  ui_story_5079_50791501_64_dialog_content = "No... ¡No de esta manera! Quiero usar mi poder para luchar contra los Eclipsites...",
  ui_story_5079_50791501_65_dialog_content = "No perder el control en este lugar...",
  ui_story_5079_50791501_66_dialog_content = "Estrépito, estrépito...",
  ui_story_5079_50791501_67_dialog_content = "¿Eh? ¿Mi poder... rompió a ese ídolo?",
  ui_story_5079_50791501_68_dialog_content = "No... Todavía está ahí. Tú, por otro lado... ¿Te abandonó?",
  ui_story_5079_50791501_69_dialog_content = "Justo como la deidad nos abandonó en el Viejo Pueblo y nos dejó morir a manos de los Eclipsites...",
  ui_story_5079_50791501_70_dialog_content = "Perdí a mi madre y mi hogar... Por todo lo que sabemos, papá y yo podríamos ser destrozados por los Eclipsites mañana.",
  ui_story_5079_50791501_71_dialog_content = "Y tú... Tienes que pasar el resto de tus días en el suelo frío, mirando la estatua que una vez te perteneció...",
  ui_story_5079_50791501_72_dialog_content = "¿Duele? ¿Puedes decirme... por qué tenemos que vivir con este tipo de dolor?",
  ui_story_5079_50791501_73_dialog_content = "No... Eso no es...",
  ui_story_5079_50791501_74_dialog_content = "Tú y yo... No somos iguales... así que deja de fingir ser tan miserable.",
  ui_story_5079_50791501_75_dialog_content = "Tu estatua está justo allí, así que todavía tienes un lugar al que llamar hogar... Está bien, solo usa mi poder para regresar a tu lugar legítimo...",
  ui_story_5079_50791501_76_dialog_content = "<color=#e8d9bb>La chica recogió el pedazo roto de la estatua como si fuera la última brasa en un mundo de noche eterna.</color>",
  ui_story_5079_50791501_77_dialog_content = "<color=#e8d9bb>Con un pequeño pero justificado deseo, ella puso toda su fuerza en ello...</color>",
  ui_story_5079_50791501_78_dialog_content = "...",
  ui_story_5079_50791501_79_dialog_content = "Ahora ve. Vuelve a casa...",
  ui_story_5079_50791501_80_dialog_content = "...",
  ui_story_5079_50791501_81_dialog_content = "¿Estás diciendo... que quieres quedarte conmigo? ¿Lo harás... de verdad?",
  ui_story_5079_50791501_82_dialog_content = "Mi poder... Se siente mucho más tranquilo ahora. ¿Me estás ayudando a llevar la mayor parte de la carga?",
  ui_story_5079_50791501_83_dialog_content = "Me siento tan cálido y cómodo ahora... Gracias... Muchas gracias...",
  ui_story_5079_50791501_84_dialog_content = "Yo... ¿fui yo quien pidió a Hunting Stone que se quedara conmigo?",
  ui_story_5079_50791501_85_dialog_content = "Fui yo quien le dio mi poder...",
  ui_story_5079_50791501_86_dialog_content = "Sí... Este poder... Todo te pertenece.",
  ui_story_5079_50791501_87_dialog_content = "Tenías tanto miedo de decepcionar a tu padre... por eso te negaste a confiar en tu propia fuerza.",
  ui_story_5079_50791501_88_dialog_content = "Por esa razón, te hiciste creer que este poder provenía de mí...",
  ui_story_5079_50791501_89_dialog_content = "No soy tan débil como me haces parecer... Solo olvidé, eso es todo.",
  ui_story_5079_50791501_90_dialog_content = "Quizás, pero en algún lugar profundo de tu corazón, siempre recuerdas.",
  ui_story_5079_50791501_91_dialog_content = "No era que no tuvieras confianza en tus habilidades, de hecho, solo querías que alguien se quedara a tu lado sin importar qué...",
  ui_story_5079_50791501_92_dialog_content = "Así que hice exactamente eso. Fui tu compañero silencioso, o al menos quería que te sintieras así con respecto a mí.",
  ui_story_5079_50791501_93_dialog_content = "Un compañero silencioso aún debería hablar cuando la situación lo requiera.",
  ui_story_5079_50791501_94_dialog_content = "Ojalá me hubieras dicho antes que podías hablar. Yo...",
  ui_story_5079_50791501_95_dialog_content = "Puede que no sea la persona más directa cuando se trata de estas cosas... ¡pero aún así quiero saber cómo te sientes a veces!",
  ui_story_5079_50791501_96_dialog_content = "Es porque fuiste tan honesto justo ahora que finalmente elegí hablar...",
  ui_story_5079_50791501_97_dialog_content = "Todavía recuerdo lo amable que fuiste conmigo esa noche... He estado esperando el momento en que finalmente puedas aceptarme.",
  ui_story_5079_50791501_98_dialog_content = "¡Por eso puedo estar a tu lado y ayudarte de nuevo!",
  ui_story_5079_50791501_99_dialog_content = "¡En cuanto a tu poder, te lo devolveré todo!",
  ui_story_5079_50791501_100_dialog_content = "Conozco tu fuerza y bondad mejor que nadie, Pact.",
  ui_story_5079_50791501_101_dialog_content = "¡Ahora supera el dolor de tu pasado y derrota a ese monstruo de zanahoria!",
  ui_story_5079_50791501_102_dialog_content = "Humph, no tienes que devolvérmelo...",
  ui_story_5079_50791501_103_dialog_content = "Después de todo, hemos sido <color=#FFB400>nosotros</color> todo este tiempo, ¿no es así?",
  ui_story_5079_50791501_104_dialog_content = "<color=#e8d9bb>¡Whoosh! ¡Crack!</color>",
  ui_story_5079_50791501_105_dialog_content = "Humph, estas ataduras son un juego de niños comparado con lo que realmente podemos hacer!",
  ui_story_5079_50791501_106_dialog_content = "¿Por qué esta arma no me obedece?",
  ui_story_5079_50791501_107_dialog_content = "Todavía quiero saborear un poco más tu sufrimiento...",
  ui_story_5079_50791501_108_dialog_content = "Pero parece... que nuestro tiempo se ha agotado. ¡Difunde, mi delicioso aroma a zanahoria!",
  ui_story_5079_50791501_109_dialog_content = "Graaaaaah—",
  ui_story_5079_50791501_110_dialog_content = "Qué chiste. ¿Crees que estos pececillos son suficientes para detenerme? Je... Supongo que eso significa que no eres mucho más fuerte que ellos, ¿eh?",
  ui_story_5079_50791501_111_dialog_content = "¡Pequeño, pequeño!",
  ui_story_5079_50791501_112_dialog_content = "¡S-Silencio!",
  ui_story_5079_50791501_113_dialog_content = "¡Mientras esta cosa esté bajo mi control, no tienes poder aquí!",
  ui_story_5079_50791501_114_dialog_content = "Yo, por otro lado, solo necesito consumir el odio de Popo... ¡Secuaces! ¡Compre a su maestro algo más de tiempo!",
  ui_story_5079_50791501_115_dialog_content = "Graaaaaah—",
  ui_story_5079_50791501_116_dialog_content = "¿Escapando con la Piedra de Caza, eh? Gran error...",
  ui_story_5079_50791501_117_dialog_content = "Mientras nuestros corazones sean uno, cualquier distancia entre nosotros solo hará nuestro vínculo más fuerte.",
  ui_story_5079_50791501_118_dialog_content = "No dejaré que lastimes a Popo...",
  ui_story_5079_50791501_119_dialog_content = "¡Y no dejaré que nadie más se escape con mi Piedra de Caza!",
  ui_story_5079_50791601_1_dialog_content = "<color=#e8d9bb>Pam, pam, pam!</color>",
  ui_story_5079_50791601_2_dialog_content = "Graaah...",
  ui_story_5079_50791601_3_dialog_content = "¡Fuera de mi camino, debiluchos!",
  ui_story_5079_50791601_4_dialog_content = "¡Esto no puede ser! ¿Cómo me alcanzaste tan rápido?",
  ui_story_5079_50791601_5_dialog_content = "<color=#e8d9bb>Swoosh—</color>",
  ui_story_5079_50791601_6_dialog_content = "¡Mantén tus sucios tentáculos lejos de Popo, monstruo!",
  ui_story_5079_50791601_7_dialog_content = "Es... Eres tú...",
  ui_story_5079_50791601_8_dialog_content = "Lo siento, llego tarde. No te preocupes, estás a salvo ahora...",
  ui_story_5079_50791601_9_dialog_content = "Yo... Sabía que vendrías a salvarme. Nunca lo dudé... ni por un segundo...",
  ui_story_5079_50791601_10_dialog_content = "Lamento que mi inutilidad me haya hecho ser capturado de nuevo. ¿Es mi padre—",
  ui_story_5079_50791601_11_dialog_content = "Como dije, ya no tienes que preocuparte... Déjame todo a mí.",
  ui_story_5079_50791601_12_dialog_content = "¡No... No te atrevas a mirarme como si fuera basura!",
  ui_story_5079_50791601_13_dialog_content = "¡Todavía no te he mostrado todo mi poder!",
  ui_story_5079_50791601_14_dialog_content = "¿Es así? Bueno. Tampoco me importaría verlo por mí mismo.",
  ui_story_5079_50791601_15_dialog_content = "Estaba dispuesto a perdonarte la vida si solo me devolvías mi Piedra Cazadora... pero ya no.",
  ui_story_5079_50791601_16_dialog_content = "¡Ya que insistes en ser así, permíteme mostrarte también todo mi poder!",
  ui_story_5079_50791602_1_dialog_content = "<color=#828282>¡Whoosh!</color>",
  ui_story_5079_50791602_2_dialog_content = "¡Imposible! Mis zarcillos... Ay... ¿Cómo pudiste...",
  ui_story_5079_50791602_3_dialog_content = "!",
  ui_story_5079_50791602_4_dialog_content = "No... ¡No te vayas!",
  ui_story_5079_50791602_5_dialog_content = "¡Se acabó para ti!",
  ui_story_5079_50791602_6_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5079_50791602_7_dialog_content = "¡Noooo!",
  ui_story_5079_50791602_8_dialog_content = "!",
  ui_story_5079_50791602_9_dialog_content = "¿Eh? ¿Por qué estás tan feliz? ¡Ya cortalo!",
  ui_story_5079_50791602_10_dialog_content = "¿No deberías estar feliz también, Pact?",
  ui_story_5079_50791602_11_dialog_content = "\"¡No dejaré que nadie más se escape con MI Piedra de Caza!\" Eso es lo que dijiste, ¿verdad?",
  ui_story_5079_50791602_12_dialog_content = "?",
  ui_story_5079_50791602_13_dialog_content = "¡Tú... Debes haberme oído mal! ¡Yo no dije nada parecido!",
  ui_story_5079_50791602_14_dialog_content = "¡Lo que creas que escuchaste, olvídate de ello ahora mismo!",
  ui_story_5079_50791602_15_dialog_content = "Está bien...",
  ui_story_5079_50791602_16_dialog_content = "Pero parece que finalmente has comprendido que no me necesitas para comandar tu poder.",
  ui_story_5079_50791602_17_dialog_content = "¿Entonces por qué molestarse en llevarme de vuelta? Siempre puedo dejar de seguirte si realmente lo deseas...",
  ui_story_5079_50791602_18_dialog_content = "¿Decir ah?",
  ui_story_5079_50791602_19_dialog_content = "La única razón por la que las cosas empeoraron tanto fue porque te entregué a ese estúpido monstruo de zanahoria.",
  ui_story_5079_50791602_20_dialog_content = "Si un Eclipsite te atrapa, ¡quién sabe qué tipo de problemas causará!",
  ui_story_5079_50791602_21_dialog_content = "...",
  ui_story_5079_50791602_22_dialog_content = "Tu gusto al elegir a tu futuro maestro también es bastante malo. Quiero decir, ¿una zanahoria? ¿En serio? ¡No puedes simplemente ir con lo que encuentres por ahí!",
  ui_story_5079_50791602_23_dialog_content = "La única persona digna de ser tu maestro soy yo, la gran y noble Señora Pact!",
  ui_story_5079_50791602_24_dialog_content = "¿Entender?",
  ui_story_5079_50791602_25_dialog_content = "...",
  ui_story_5079_50791602_26_dialog_content = "Estás jugando conmigo, ¿verdad? ¡Deja de fingir que no puedes hablar!",
  ui_story_5079_50791602_27_dialog_content = "No lo soy, es solo que... realmente pareces noble ahora mismo...",
  ui_story_5079_50791602_28_dialog_content = "Ah...",
  ui_story_5079_50791602_29_dialog_content = "<size=30>También acepto cumplidos como \"hermosa\" y \"adorable\", sabes...</size>",
  ui_story_5079_50791602_30_dialog_content = "¡Aún no he perdido!",
  ui_story_5079_50791602_31_dialog_content = "Yo... Yo crearé... un mundo perfecto para todas las zanahorias! Uno donde nadie me menospreciará...",
  ui_story_5079_50791602_32_dialog_content = "Un mundo donde seré deseado, aceptado... ¡y se me permitirá vivir!",
  ui_story_5079_50791602_33_dialog_content = "Después de todo lo que ha pasado, ¿sigues aferrado a tu resentimiento?",
  ui_story_5079_50791602_34_dialog_content = "Simplemente tendremos que sacarte de tu—",
  ui_story_5079_50791602_35_dialog_content = "W-<size=45>¡Espera!</size>",
  ui_story_5079_50791602_36_dialog_content = "?",
  ui_story_5079_50791602_37_dialog_content = "¡Lo siento! Nunca debí haberte dejado aquí ni haber dicho todas esas cosas crueles...",
  ui_story_5079_50791602_38_dialog_content = "Mis palabras te lastimaron, ¿verdad?",
  ui_story_5079_50791602_39_dialog_content = "Fue duro, ¿verdad? Pasar todos esos días aquí solo...",
  ui_story_5079_50791602_40_dialog_content = "Nadie con quien hablar, nadie te necesita... Entiendo cómo se siente eso...",
  ui_story_5079_50791602_41_dialog_content = "Pero si estás dispuesto a darme otra oportunidad...",
  ui_story_5079_50791602_42_dialog_content = "¿Podríamos... podríamos ser amigos, por favor?",
  ui_story_5079_50791602_43_dialog_content = "...",
  ui_story_5079_50791602_44_dialog_content = "Quiero plantarte en el lugar más soleado y fértil de nuestro jardín.",
  ui_story_5079_50791602_45_dialog_content = "Quiero que tomes todos los nutrientes que necesitas para crecer grande y fuerte y convertirte en una zanahoria que a cualquiera le encantaría comer!",
  ui_story_5079_50791602_46_dialog_content = "Uh, ¿Popo? Ofrecerse a comerlo no es lo más reconfortante que se puede decir... ¿No preferirías que tuviera una vida larga y saludable?",
  ui_story_5079_50791602_47_dialog_content = "<color=#e8d9bb>¡Maricón!</color>",
  ui_story_5079_50791602_48_dialog_content = "Po... Popo—",
  ui_story_5079_50791602_49_dialog_content = "¿Significa esto... que me perdonas?",
  ui_story_5079_50791602_50_dialog_content = "¡Popo!",
  ui_story_5079_50791602_51_dialog_content = "Sabes, las zanahorias también pueden ser bastante lindas...",
  ui_story_5079_50791602_52_dialog_content = "¿Qué dices? ¿Deberíamos darle otra oportunidad a las zanahorias?",
  ui_story_5079_50791602_53_dialog_content = "Eh... creo que necesito un poco más de tiempo para pensar en eso.",
  ui_story_5079_50791602_54_dialog_content = "(Entonces, su idea de una buena vida es ser comido por alguien que le gusta...)",
  ui_story_5079_50791602_55_dialog_content = "(Bueno, mientras eso sea lo que le da satisfacción...)",
  ui_story_5079_50791602_56_dialog_content = "... ¿Popo?",
  ui_story_5079_50791602_57_dialog_content = "¿Padre? ¡Ahh! ¡Intenta no moverte! Estás cubierto de heridas...",
  ui_story_5079_50791602_58_dialog_content = "Apenas siento algo... Verte vivo y bien, eso es todo lo que necesito...",
  ui_story_5079_50791602_59_dialog_content = "Todo esto fue mi culpa, Popo. Nunca debí haberte ordenado tanto... o forzarte a aceptar mis ideas...",
  ui_story_5079_50791602_60_dialog_content = "Estaba demasiado obsesionada con darnos una vida familiar \"ideal\".",
  ui_story_5079_50791602_61_dialog_content = "Y puse el peso de mis ambiciones sobre tus hombros.",
  ui_story_5079_50791602_62_dialog_content = "Después de todo, mi vida nunca ha significado mucho. No he hecho más que sufrir pérdida tras pérdida. Incluso...",
  ui_story_5079_50791602_63_dialog_content = "Incluso perdí al amor de mi vida, tu mamá... Todo es porque no pude protegerla...",
  ui_story_5079_50791602_64_dialog_content = "Padre... Todo este tiempo, has estado ocultando tu dolor por la muerte de mi madre...",
  ui_story_5079_50791602_65_dialog_content = "Y esta vez, no pude protegerte...",
  ui_story_5079_50791602_66_dialog_content = "Cuando huiste de casa, no pude dejar de preguntarme algo: ¿qué exactamente había proporcionado para mi familia?",
  ui_story_5079_50791602_67_dialog_content = "¿No fue más que recuerdos dolorosos?",
  ui_story_5079_50791602_68_dialog_content = "Todo lo que quería era convertirme algún día en una familia de comerciantes adinerados y cenar en la misma mesa que los nobles de Lumopolis.",
  ui_story_5079_50791602_69_dialog_content = "Ver cómo creces y te conviertes en una estrella brillante que capta la atención de todos, incluyendo la de la nobleza...",
  ui_story_5079_50791602_70_dialog_content = "Estaba tan cegado por mi sueño que nunca aprecié nuestras comidas sencillas en nuestra pequeña tienda ni noté la forma en que sonreías cuando comías tu comida favorita...",
  ui_story_5079_50791602_71_dialog_content = "¡Aprovechar esos momentos es lo que significa estar vivo! ¡Ser verdaderamente feliz!",
  ui_story_5079_50791602_72_dialog_content = "Yo—",
  ui_story_5079_50791602_73_dialog_content = "¡Yo... yo quiero que tú también seas feliz, papá! ¡Por eso seguiré dando lo mejor de mí!",
  ui_story_5079_50791602_74_dialog_content = "¡Te escucharé más y dejaré de causarte tantos problemas! Siempre y cuando...",
  ui_story_5079_50791602_75_dialog_content = "¡Mientras estemos juntos! Seré feliz para siempre y siempre mientras esté contigo, papá!",
  ui_story_5079_50791602_76_dialog_content = "<size=30>Honestamente... ¿No crees que deberías ir a casa antes de hablar de todas estas cosas sentimentales?</size>",
  ui_story_5079_50791602_77_dialog_content = "<size=30>Casi digo algo también... Esto es muy incómodo.</size>",
  ui_story_5079_50791602_78_dialog_content = "¿Eh? ¿Qué hay en el rabillo de mi ojo?",
  ui_story_5079_50791602_79_dialog_content = "¿Está lloviendo? Bien, eso debería llevarse el olor de las zanahorias...",
  ui_story_5079_50791602_80_dialog_content = "*lloriqueo* ¡Deja de llorar, tonto!",
  ui_story_5079_50791602_81_dialog_content = "Ah... Sería mejor que no arruine mi ropa por estas lágrimas.",
  ui_story_5079_50791602_82_dialog_content = "Al final—",
  ui_story_5079_50791602_83_dialog_content = "Al final, te diste cuenta del sueño de tu padre, ¿no es así?",
  ui_story_5079_50791602_84_dialog_content = "¡Ay!",
  ui_story_5079_50791602_85_dialog_content = "Antes de realizar cualquier tipo de negocio, lo más importante que puedes hacer es lucir digno y presentable.",
  ui_story_5079_50791602_86_dialog_content = "Solo de esta manera los clientes ricos te darán su tiempo y su patrocinio.",
  ui_story_5079_50791602_87_dialog_content = "Tú... ¿Cuándo lo descubriste?",
  ui_story_5079_50791602_88_dialog_content = "Cuando accidentalmente lo llamaste \"papá\" antes, se volvió demasiado obvio.",
  ui_story_5079_50791602_89_dialog_content = "Parece que encontraste tu respuesta, Pact.",
  ui_story_5079_50791602_90_dialog_content = "No pienses que eres inteligente o algo así... Solo me equivoqué, eso es todo...",
  ui_story_5079_50791602_91_dialog_content = "¡Y deja de mirarme! ¡Nadie tiene permitido verme cuando estoy llorando!",
  ui_story_5079_50791602_92_dialog_content = "¡Oye! ¡No te vayas!",
  ui_story_5079_50791602_93_dialog_content = "¿Eh? UH oh...",
  ui_story_5079_50791602_94_dialog_content = "<color=#e8d9bb>Pam—</color>",
  ui_story_5079_50791602_95_dialog_content = "...",
  ui_story_5079_50791602_96_dialog_content = "Esa es la segunda vez que te encuentras conmigo así, Popo.",
  ui_story_5079_50791602_97_dialog_content = "¡No me importa! ¡No puedes irte aún! ¡No puedes! Yo... ¡Aún no te he agradecido correctamente!",
  ui_story_5079_50791602_98_dialog_content = "No dije que me iba, solo... <size=30>no quería que ninguno de los dos me viera así.</size>",
  ui_story_5079_50791602_99_dialog_content = "Además, no tienes que agradecerme por nada... Solo estaba haciendo lo que se suponía que debía hacer.",
  ui_story_5079_50791602_100_dialog_content = "¡Sí, claro! ¡Solo no quieres admitir que eres una buena persona! ¡Pero ahora sé que eres una de las personas más amables que existen!",
  ui_story_5079_50791602_101_dialog_content = "Gracias por ayudarme a reconciliarme con mi padre, y gracias...",
  ui_story_5079_50791602_102_dialog_content = "¡Por mostrarme... que soy muy amado!",
  ui_story_5079_50791602_103_dialog_content = "¡Voy a... voy a hacer lo mejor que pueda!",
  ui_story_5079_50791602_104_dialog_content = "A partir de ahora, voy a trabajar duro para convertirme en una persona fuerte y amable, ¡justo como tú!",
  ui_story_5079_50791602_105_dialog_content = "¿Yo? Je... No soy precisamente digno de ser llamado un modelo a seguir.",
  ui_story_5079_50791602_106_dialog_content = "Solo sigue avanzando y estarás bien, Popo.",
  ui_story_5079_50791602_107_dialog_content = "Sigue avanzando, sigue a tu corazón y nunca mires atrás.",
  ui_story_5079_50791602_108_dialog_content = "Haz eso, y conocerás todo tipo de personas maravillosas: personas que te respetan, personas que se ríen contigo y personas que te llenan de calidez durante todo tu viaje.",
  ui_story_5079_50791602_109_dialog_content = "Si alguna vez te pierdes, solo levanta la cabeza...",
  ui_story_5079_50791602_110_dialog_content = "Observa detenidamente el cielo estrellado, y encontrarás las respuestas que necesitas, justo como yo lo hice.",
  ui_story_5079_50791602_111_dialog_content = "Porque...",
  ui_story_5079_50791602_112_dialog_content = "Soy tú, Popo.",
  ui_story_5079_50791602_113_dialog_content = "Espera... ¿Eres tú mi yo del futuro?",
  ui_story_5079_50791602_114_dialog_content = "¡Realmente espero poder ser tan increíble como tú algún día!",
  ui_story_5079_50791602_115_dialog_content = "Lo harás, confía en mí.",
  ui_story_5079_50791602_116_dialog_content = "Ah, papá me está diciendo que venga a casa ahora...",
  ui_story_5079_50791602_117_dialog_content = "No importa a dónde vayas, no te olvides de mí, ¿vale?",
  ui_story_5079_50791602_118_dialog_content = "Popo...",
  ui_story_5079_50791602_119_dialog_content = "Una vez que recuerdo algo, nunca lo olvidaré.",
  ui_story_5079_50791602_120_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50791602_121_dialog_content = "Es hora de que nos pongamos en marcha.",
  ui_story_5079_50791602_122_dialog_content = "Sí, tienes razón, pero realmente quiero saber...",
  ui_story_5079_50791602_123_dialog_content = "En el futuro, ¿tendrá ella una infancia más feliz que yo aquí en Folta?",
  ui_story_5079_50791602_124_dialog_content = "¿Podrá ella sonreír por todas las veces que yo no pude?",
  ui_story_5079_50791602_125_dialog_content = "¿Nunca tendrá que sentir la misma ira o tristeza que yo sentí?",
  ui_story_5079_50791602_126_dialog_content = "¿Podrá... pasar su vida sin enfrentar una infancia dolorosa?",
  ui_story_5079_50791602_127_dialog_content = "... Estoy seguro de que estará bien. Después de todo, ya has curado a tantos otros, incluyéndote a ti mismo.",
  ui_story_5079_50791602_128_dialog_content = "Recuerda, eres la amable y noble Lady Pact.",
  ui_story_5079_50791602_129_dialog_content = "Encontraste tu camino hace mucho tiempo. Es justo como dijiste—",
  ui_story_5079_50791602_130_dialog_content = "\"Sigue avanzando, sigue a tu corazón y nunca mires atrás.\"",
  ui_story_5079_50791602_131_dialog_content = "El futuro de Popo está lleno de muchas maravillosas posibilidades, ¡y el tuyo también!",
  ui_story_5079_50791602_132_dialog_content = "Justo como pensé, solo hablas cuando es hora de dar un gran discurso, y luego no hay quien te pare.",
  ui_story_5079_50791602_133_dialog_content = "No te pongas demasiado sentimental. Mis problemas no se solucionan solo porque dijiste unas pocas palabras amables.",
  ui_story_5079_50791602_134_dialog_content = "Ahora que lo pienso, realmente me recuerdas a mi Piedra de Caza a veces, PlayerName.",
  ui_story_5079_50791602_135_dialog_content = "¿Eh? ¿Cuándo lo descubriste?",
  ui_story_5079_50791602_136_dialog_content = "No fue difícil. Todo lo que tuve que hacer fue armar tu pequeña actuación y tu costumbre de dar charlas motivadoras.",
  ui_story_5079_50791602_137_dialog_content = "Esta es la sabiduría que obtuve de las reglas. ¿Quieres que te las explique?",
  ui_story_5079_50791602_138_dialog_content = "...",
  ui_story_5079_50791602_139_dialog_content = "¡Ya te lo dije: deja de fingir que no puedes hablar! ¡Hace que las cosas parezcan incómodas!",
  ui_story_5079_50791602_140_dialog_content = "¡Yo... Yo en realidad estoy de acuerdo contigo en muchas cosas!",
  ui_story_5079_50791602_141_dialog_content = "¡Todavía tengo tantas palabras sin decir... y cosas sin hacer!",
  ui_story_5079_50791602_142_dialog_content = "Volvamos al mundo real... aquel en el que realmente vivimos.",
  ui_story_5079_50791602_143_dialog_content = "Ya he decidido darte una misión... una que solo tú puedes completar.",
  ui_story_5079_50791602_144_dialog_content = "Y antes de que preguntes, no hay forma de rechazarlo... ¡A-Así que por favor haz un poco de tiempo para ello!"
}
return config
